"""A chapter 3 analysis questions, derived from original equations and errata."""
from qd1000_next_common import *

def a(n,o,qp,ap,stem,ans,exp,topic='时域分析 / 响应计算',notes=''):
    return C(3,'分析题',n,o+' 2025',qp,ap,stem,ans,exp,topic,notes)

rr,count=routh([1,2,9,10,1,2]);assert count==2
a(1,'浙江理工大学','66','123–124',r'单位负反馈开环 $G=(s+2)/[s^2(s^3+2s^2+9s+10)]$。用劳斯判据判定闭环稳定性。',
 '闭环不稳定，有2个右半平面极点。',r'特征方程为 $1+G=0$，清分母得到 $D=s^5+2s^4+9s^3+10s^2+s+2$。'+'\n\n'+rr,'时域分析 / 劳斯稳定')
a(2,'浙江理工大学','66','124–125',r'单位负反馈前向 $6/[s(s+5)]$。等价闭环运动方程 $\ddot c+5\dot c+6c=6r$，$c(0^-)=-2,\dot c(0^-)=-2$。施加单位阶跃，求总响应。',
 r'$$c(t)=1-11e^{-2t}+8e^{-3t},\qquad t\ge0.$$ ',
 r'''闭环分母为 $(s+2)(s+3)$。对带初值的运动方程作单边变换：
$$ (s^2+5s+6)C=\frac6s-2s-12.$$
部分分式为 $C=1/s-11/(s+2)+8/(s+3)$，反变换得答案。复核 $c(0^+)=1-11+8=-2$、$\dot c(0^+)=22-24=-2$，且终值1。只用零初值传递函数乘阶跃会遗漏自由响应。''')
a(3,'中国石油大学（华东）','67','125–126',r'单位负反馈 $G=K/[s(Ts+1)]$。（1）$K=4,T=1$，求单位阶跃超调量、5%调节时间的工程估算，以及 $r=5t$ 的稳态误差；（2）$T=1$，若 $\zeta=0.5$，求 $K$。',
 r'（1）$\sigma=e^{-\pi/\sqrt{15}}\approx44.43\%$，$t_s\approx6\,\mathrm s$，$e_{ss}=1.25$；（2）$K=1$。',
 r'闭环分母 $Ts^2+s+K$，故 $\omega_n=\sqrt{K/T}$、$\zeta=1/(2\sqrt{KT})$。第一问得 $\omega_n=2,\zeta=1/4$，代入典型二阶超调公式得到44.43%，按 $3/(\zeta\omega_n)$ 得6秒。$K_v=K=4$，斜坡误差为 $5/4$。第二问由 $1/(2\sqrt K)=0.5$ 得 $K=1$。','时域分析 / 二阶性能')
a(4,'中国石油大学（北京）','67','126–127',r'零初值 RLC 网络：输入依次经过串联电感 $L$、电阻 $R$ 到输出节点，输出由电容 $C$ 接地，无外负载。（1）列微分方程并求 $U_o/U_i$；（2）$R=1\,\Omega,L=2\,\mathrm H,C=0.0125\,\mathrm F$，求 $\omega_n,\zeta$。',
 r'''$$LC\ddot u_o+RC\dot u_o+u_o=u_i,\quad \frac{U_o}{U_i}=\frac1{LCs^2+RCs+1}.$$
（2）$\omega_n=\sqrt{40}\approx6.325\,\mathrm{rad/s}$，$\zeta=1/(8\sqrt{10})\approx0.03953$。''',
 r'电路电流 $i=C\dot u_o$，KVL 为 $u_i=L\dot i+Ri+u_o$。代入得微分方程，零初值变换得传递函数。标准化分母为 $s^2+(R/L)s+1/(LC)$，因此 $\omega_n=1/\sqrt{LC}$、$\zeta=(R/2)\sqrt{C/L}$。题中数字为 $R=1,L=2$，不能将单位符号误识为额外的0。','建模 / 传递函数')
a(5,'北京化工大学','68','127–129',r'单位负反馈开环 $G=K/[s(s^2+7s+17)]$，$K>0$。（1）求临界等幅振荡的 $K$ 与频率；（2）求全部闭环极点实部小于 $-2$ 的 $K$ 范围。',
 r'（1）$K=119$，$\omega=\sqrt{17}\,\mathrm{rad/s}$；（2）$14<K<15$。',
 r'''闭环特征式 $D=s^3+7s^2+17s+K$。劳斯首列 $1,7,(119-K)/7,K$，故稳定区为 $0<K<119$。在临界值119，$D=(s+7)(s^2+17)$。
第二问令 $s=z-2$，则 $D(z-2)=z^3+z^2+z+K-14$。要求原根实部小于 $-2$，等价于新多项式 Hurwitz，三阶条件为 $K-14>0$ 且 $1>K-14$，即 $14<K<15$。''','时域分析 / 劳斯稳定')
a(6,'北京化工大学','68','129–130',r'单位负反馈系统的零初值单位阶跃响应为 $y=1+0.5e^{-6t}-1.5e^{-2t}$。（1）求闭环传递函数；（2）求 $\zeta,\omega_n$；（3）$r=(0.5+t)1(t)$，求稳态误差。',
 r'$$\Phi=\frac{12}{s^2+8s+12},\quad \omega_n=2\sqrt3,\quad\zeta=\frac2{\sqrt3},\quad e_{ss}=\frac23.$$ ',
 r'由 $\Phi=sY$ 通分得分子12。分母比较得 $\omega_n=\sqrt{12}$、$\zeta=8/(2\sqrt{12})$。单位负反馈开环 $G=\Phi/(1-\Phi)=12/[s(s+8)]$，闭环稳定且为 I 型，故阶跃误差为零，$K_v=12/8=3/2$，单位斜坡误差为 $1/K_v=2/3$。','时域分析 / 反求参数')
a(7,'北京化工大学','69','130–131',r'系统满足 $E=R-C$，$C=K_2E/[s(T_2s+1)]+G_cN$，$G_c=K_1/(T_1s+1)$，$T_1,T_2,K_2>0$。零初值，$r=n=t1(t)$，求稳态误差。',
 r'$e_{ss}=(1-K_1)/K_2$。',
 r'由输出方程得 $E=(R-G_cN)/(1+G)$，其中 $G=K_2/[s(T_2s+1)]$。闭环分母 $T_2s^2+s+K_2$ 稳定。代入 $R=N=1/s^2$，有 $sE=(1-G_c)/[s(1+G)]$，取 $s\to0$ 得 $(1-K_1)/K_2$。给定与扰动同为斜坡，但扰动在输出处以正号注入，所以其误差贡献为负；不能把两贡献的绝对值相加。','时域分析 / 稳态误差')
a(8,'北京化工大学','69','131–133',r'系统运动方程 $\ddot y+3\dot y+2y=2r$，对应闭环传递函数 $2/[(s+1)(s+2)]$。$y(0^-)=-1,\dot y(0^-)=0$，输入单位阶跃，求总响应。',
 r'$$y(t)=1-4e^{-t}+2e^{-2t},\quad t\ge0.$$ ',
 r'单边变换得 $(s^2+3s+2)Y=2/s-s-3$。部分分式为 $Y=1/s-4/(s+1)+2/(s+2)$。初值检查：$1-4+2=-1$，导数 $4-4=0$；终值为1。题目已明确非零初始运动方程，因此不能仅用 $Y=\Phi/s$。')
a(9,'北京化工大学','69','133',r'闭环特征多项式 $s^4+2s^3+Ts^2+10s+100$。求渐近稳定时 $T$ 的范围。',
 r'$T>25$。',r'劳斯首列为 $1,2,T-5,10(T-25)/(T-5),100$。首先 $T-5>0$，再要求第四项为正，得到 $T>25$。在 $T=25$ 时出现全零行，存在虚轴根，必须从渐近稳定区排除。','时域分析 / 劳斯稳定')
a(10,'河海大学','70','134–135',r'单位负反馈开环 $G=K/[(s+2)(s+4)(s^2+6s+25)]$，$K>0$。（1）稳定时能否使单位阶跃误差 $e_{ss}\le0.2$？若能，求范围。（2）求临界振荡增益与频率。',
 r'（1）不能；（2）$K_{cr}=2665/4=666.25$，$\omega=\sqrt{66}/2\,\mathrm{rad/s}$。',
 r'''展开闭环分母为 $s^4+12s^3+69s^2+198s+200+K$。劳斯第三行首项为 $105/2$，第四行首项的符号由 $7995-12K$ 决定，故 $0<K<2665/4$。
位置误差系数 $K_p=K/200$，要求 $1/(1+K/200)\le0.2$ 得 $K\ge800$，与稳定区没有交集。
临界时辅助多项式为 $(105/2)s^2+(200+K_{cr})$，其虚根满足 $\omega^2=(200+K_{cr})/(105/2)=33/2$，得到所列频率。''','时域分析 / 劳斯稳定')
a(11,'河南科技大学','70','136',r'系统满足 $E=R-C$、$U=(1+1/s)E-asC$、$C=10U/[s(s+1)]$。用劳斯判据求稳定时实参数 $a$ 的范围。',
 r'$a>0$。',r'将方程联立，闭环分母为 $s^3+(1+10a)s^2+10s+10$。三阶稳定条件为 $1+10a>0$ 和 $10(1+10a)>10$，后者更强，得到 $a>0$。在 $a=0$ 时分母为 $(s+1)(s^2+10)$，有一对纯虚根，不能纳入稳定区。','时域分析 / 劳斯稳定')
a(12,'济南大学','70','136',r'单位负反馈开环 $G=K/[s(1+s/3)(1+s/4)]$。求使全部闭环根实部严格小于 $-1$ 的 $K$ 范围。',
 '$1/2<K<5/6$。',r'先清除时间常数分母，闭环特征式为 $D=s^3+7s^2+12s+12K$。令 $s=z-1$，有 $D(z-1)=z^3+4z^2+z+12K-6$。三阶 Hurwitz 条件为 $12K-6>0$ 且 $4>12K-6$，从而 $1/2<K<5/6$。','时域分析 / 劳斯稳定')
a(13,'南昌大学','71','137–138',r'液位计模型 $1/(Ts+1)$，阶跃液位变化30秒后示数达到变化量的95%。（1）求 $T$；（2）实际液位以 $0.2\,\mathrm{cm/s}$ 增长，求测量滞后稳态误差。',
 r'$T=30/\ln20\approx10.014\,\mathrm s$，$e_{ss}=0.2T\approx2.003\,\mathrm{cm}$。工程近似为10秒与2厘米。',
 r'一阶阶跃相对误差为 $e^{-t/T}$，由 $e^{-30/T}=0.05$ 得精确时间常数。斜坡输入 $R=0.2/s^2$，测量误差 $E=[1-1/(Ts+1)]R=0.2T/[s(Ts+1)]$。终值为 $0.2T$，正值表明示数落后于实际液位。','时域分析 / 一阶响应')
a(14,'四川大学','71','138–140',r'系统为外单位负反馈，前向输入比较点先减去测速反馈 $asC$，再经 $K/[s(s+2)]$ 输出。（1）$a=0,K=8$，求 $\zeta,\omega_n$ 和单位斜坡误差；（2）$K=8,\zeta=0.7$，求 $a$ 和斜坡误差；（3）要求 $e_{ss}=0.25,\zeta=0.7$，求 $K,a$。',
 r'（1）$\omega_n=2\sqrt2,\zeta=1/(2\sqrt2),e_{ss}=0.25$；（2）$a=(2.8\sqrt2-2)/8\approx0.24497$，$e_{ss}=0.7/\sqrt2\approx0.49497$；（3）$K=31.36,a=73/392\approx0.18622$。',
 r'''由 $C=K(R-C-asC)/[s(s+2)]$ 得
$$\Phi=\frac K{s^2+(2+aK)s+K}.$$
所以 $\omega_n=\sqrt K$、$\zeta=(2+aK)/(2\sqrt K)$。误差定义为外环 $R-C$，对单位斜坡
$$e_{ss}=\lim_{s\to0}\frac{1-\Phi}{s}=\frac{2+aK}{K}=\frac{2\zeta}{\omega_n}.$$
依次代入给定数值即可。第三问先由 $\omega_n=2(0.7)/0.25=5.6$ 得 $K=31.36$，再求 $a=(7.84-2)/31.36$。测速反馈改变了低频斜坡误差，不能仍用未闭合内环的 $K/2$ 作为外环速度误差系数。''','时域分析 / 二阶性能')
a(15,'中北大学','72','141–142',r'前向 $G=10/[s^2(s+10)]$，反馈 $H=1+K_ts$。比较点误差定义 $E=R-HC$。（1）求稳定的 $K_t$；（2）已知一个闭环根为 $-5$，求其余根和 $K_t$；（3）取第二问参数，输入 $r=t^2/2$，求比较点误差稳态值。另说明它与跟踪误差 $r-c$ 的区别。',
 '（1）$K_t>0.1$；（2）$K_t=2.7$，其余根 $(-5\\pm\\sqrt{17})/2$；（3）比较点误差稳态值为 $1$，跟踪误差 $r-c$ 无有限稳态值。',
 '闭环特征式 $D=s^3+10s^2+10K_ts+10$。劳斯首列 $1,10,10K_t-1,10$，所以 $K_t>0.1$。令 $D(-5)=0$ 得 $135-50K_t=0$，即 $K_t=2.7$。此时 $D=(s+5)(s^2+5s+2)$，由二次因子求得其余两根。\n比较点误差为 $E=R/(1+GH)$。在 $R=1/s^3$ 下，\n$$sE=\\frac{s+10}{D(s)},\\quad e_{ss}=1.$$\n跟踪误差为 $E_{tr}=(1-\\Phi)R$，其中 $\\Phi=10/D$。低频展开为 $1-\\Phi\\sim2.7s$，所以 $e_{tr}(t)$ 含约 $2.7t$ 的增长项，不存在有限稳态值。非单位反馈的两种误差不能混用。','时域分析 / 稳态误差')
a(16,'中北大学','72–73','142–144',r'系统满足 $E=R-C$、$U=KE+N-K_fsC$、$C=U/[s(s+2)]$。（1）求 $C/R$；（2）$\zeta=0.6,\omega_n=3$，求 $K,K_f$；（3）求超调量及2%、5%调节时间的工程估算；（4）求 $C/N$ 及单位阶跃扰动的输出终值。',
 r'''$$\frac CR=\frac K{s^2+(2+K_f)s+K},\quad K=9,\quad K_f=1.6.$$
$\sigma\approx9.48\%$，$t_s(2\%)\approx2.22\,\mathrm s$，$t_s(5\%)\approx1.67\,\mathrm s$。
$$\frac CN=\frac1{s^2+3.6s+9},\quad c_N(\infty)=\frac19.$$''',
 r'直接消去 $E,U$ 得 $[s(s+2)+K_fs+K]C=KR+N$。与标准二阶分母比较，$K=\omega_n^2=9$、$2+K_f=2\zeta\omega_n=3.6$。超调量为 $e^{-\pi\zeta/\sqrt{1-\zeta^2}}=e^{-3\pi/4}$。调节时间按 $4/(\zeta\omega_n)$ 与 $3/(\zeta\omega_n)$ 估算。单位阶跃扰动终值等于稳定扰动通道在零频处的值 $1/9$。','时域分析 / 二阶性能')
a(17,'西安理工大学','73','144–145',r'系统满足 $E=R-C$、$C=10(KE-\tau sC)/[s(s+1)]$。单位阶跃超调量16.3%，峰值时间1秒，可按 $\zeta=0.5$。（1）求 $K,\tau$；（2）求闭环根；（3）求单位阶跃稳态误差。',
 r'''$$K=\frac{2\pi^2}{15},\quad \tau=\frac{2\pi/\sqrt3-1}{10}.$$
闭环根 $-\pi/\sqrt3\pm j\pi$，阶跃稳态误差为0。''',
 r'闭环分母 $s^2+(1+10\tau)s+10K$。由 $t_p=\pi/\omega_d=1$ 得 $\omega_d=\pi$；又 $\omega_d=\omega_n\sqrt{1-0.5^2}$，故 $\omega_n=2\pi/\sqrt3$。比较常数项和一次项求得参数。闭环根由 $-\zeta\omega_n\pm j\omega_d$ 得出。闭环直流增益1，稳定时单位阶跃误差为零。','时域分析 / 反求参数')
a(18,'西安理工大学','74','145–146',r'系统满足 $E=R-sY$、$Y=(2/s)[G_1E+N-2Y]$。$G_1$ 的零初值单位阶跃响应为 $h=(8/5)(1-e^{-5t})$。（1）求 $G_1$；（2）在 $G_1$ 输入端引入由可测扰动 $N$ 驱动的前馈补偿 $G_fN$，求理想消扰的 $G_f$。',
 r'$G_1=8/(s+5)$，$G_f=-(s+5)/8$。',r'由 $G_1=sH(s)$ 得 $8/(s+5)$。加入前馈后，进入输出积分环节的扰动合成为 $(1+G_1G_f)N$。完全抵消要求 $1+G_1G_f=0$，所以 $G_f=-1/G_1=-(s+5)/8$。该理想补偿含微分作用，需要扰动可测；实际实现常用带高频滤波的近似微分，形式消扰条件不自动保证可实现性。','校正 / 前馈')
a(19,'浙江大学','74','146–148',r'双输入系统满足 $E_1=R_1-Y_1$、$E_2=R_2-Y_2$、$Y_1=G_1(K_1E_1-K_2E_2)$、$Y_2=G_2E_1$，其中 $G_1=5/[s(s+4)]$、$G_2=4/(s+10)$，$K_1,K_2>0$。求内部闭环稳定条件。',
 '$K_1>0,\\quad0<K_2<(5/2)K_1$。',
 r'''置外部输入为零，$E_1=-Y_1$、$E_2=-Y_2$、$Y_2=-G_2Y_1$。因此特征式为 $1+K_1G_1-K_2G_1G_2=0$。
清分母得到
$$D=s^3+14s^2+(40+5K_1)s+50K_1-20K_2.$$
三阶稳定条件要求 $50K_1-20K_2>0$ 且 $14(40+5K_1)>50K_1-20K_2$。第二条在 $K_1,K_2>0$ 时自动成立，故真正限制是 $0<K_2<(5/2)K_1$。''','时域分析 / 劳斯稳定')

a(20,'浙江工业大学','75','148–150',r'单位负反馈 $G=K/[(s^2+s+1)(s+1)]$，$K>0$，扰动 $N$ 在 $G$ 输入端以正号叠加。定义 $E=R-C$。（1）$N=0$ 时求单位阶跃、单位斜坡稳态误差；（2）$R=0,n=0.1\sin10t$，求使稳态误差振幅不超过0.001的稳定 $K$ 范围；（3）$R=0,n=0.1\,1(t)$，求使误差绝对值不超过0.01的稳定范围。',
 r'（1）稳定要求 $0<K<3$，阶跃误差 $1/(1+K)$，斜坡误差无穷大；（2）$0<K<3$；（3）$0<K\le1/9$。',
 r'''闭环特征式 $D=s^3+2s^2+2s+1+K$，三阶劳斯条件给出 $0<K<3$。系统为0型，第一问由误差系数得到。
扰动误差通道为 $E/N=-K/D$。在 $\omega=10$ 时，$D(j10)=K-199-j980$，稳态振幅为
$$A_e=\frac{0.1K}{\sqrt{(K-199)^2+980^2}}.$$
在 $0<K<3$ 内，$A_e<0.3/980<0.001$，故整个稳定区满足。
阶跃扰动误差为 $-0.1K/(1+K)$，解 $0.1K/(1+K)\le0.01$ 得 $K\le1/9$，再与稳定区相交。''','时域分析 / 稳态误差')
a(21,'郑州大学','75','150–152',r'前向 $G=K_1/[(T_1s+1)T_2s]$，反馈 $K_2$，参数均正。比较点误差 $E=U_i-K_2U_o$。（1）$T_1=0.2,T_2=5,K_1=25,K_2=4$，求 $\zeta,\omega_n$、5%调节时间工程值及 $u_i=3t$ 时的比较点误差；（2）如何减小超调；（3）四个参数都增大，对单位斜坡比较点稳态误差有何影响？',
 r'（1）$\zeta=0.25,\omega_n=10$，$t_s\approx1.2\,\mathrm s$，$e_{ss}=0.15$；（2）增大 $T_2$ 或减小 $T_1,K_1,K_2$ 可提高阻尼比；（3）不能只由“都增大”确定。',
 r'''闭环分母为 $T_1T_2s^2+T_2s+K_1K_2$，故
$$\omega_n=\sqrt{\frac{K_1K_2}{T_1T_2}},\quad\zeta=\frac12\sqrt{\frac{T_2}{T_1K_1K_2}}.$$
代数值得所列指标。比较点误差 $E=U_i/(1+K_2G)$，斜坡斜率为 $v$ 时 $e_{ss}=vT_2/(K_1K_2)$。因此 $T_1$ 不影响该稳态值，$T_2$ 增大会使误差增大，两个增益增大会使误差减小，同时增大须比较相对倍数。跟踪误差 $u_i-u_o$ 与比较点误差不同；本题按题给比较点计算。''','时域分析 / 二阶性能')
a(22,'中国计量大学','76','152–153',r'系统满足 $E=R-C$、$C=[(K_d/s)E+N-K_fsC]/(s+1)$，$K_d,K_f>0$。（1）$K_d=0.5,\zeta=0.5$，求 $K_f$；（2）$R=0,N=1/s^2$，求扰动稳态误差；（3）讨论两增益对该误差的影响。',
 r'$K_f=1$，$e_{ss,N}=-2$。扰动斜坡误差为 $-1/K_d$，与 $K_f$ 无关。',
 r'''联立得 $D=(1+K_f)s^2+s+K_d$，$C=(K_dR+sN)/D$。标准化分母给出 $\zeta=1/[2\sqrt{K_d(1+K_f)}]$，代入得 $K_f=1$。
扰动单独作用时 $E=-C=-sN/D$。代入单位斜坡，$sE=-1/D$，终值 $-1/K_d=-2$。正参数保证二阶闭环稳定，增大 $K_d$ 可减小误差幅值；$K_f$ 改变动态阻尼但不改变此误差的低频值。''','时域分析 / 稳态误差')
a(23,'中国矿业大学','76–77','153–155',r'系统满足 $E=R-10C$、$V=K(E+G_1N)/(s+2)+N-1.5sC$、$C=2V/[s(s+1)]$。（1）设计 $G_1$ 消除 $N$ 的全部影响；（2）一个闭环根为 $-5$，求 $K$、标准时间常数形式开环增益和其余根；（3）求5%调节时间的工程值。',
 r'$G_1=-(s+2)/K$；$K=0.75$，标准开环增益 $K_{open}=2.5K=1.875$，其余根 $-0.5\pm j\sqrt{11}/2$；$t_s\approx6\,\mathrm s$。',
 r'''先闭合速度内环，得从控制输入到 $C$ 的环节 $2/[s(s+4)]$。外环特征式为 $D=s(s+4)(s+2)+20K=s^3+6s^2+8s+20K$。令 $D(-5)=0$ 得 $K=0.75$，此时 $D=(s+5)(s^2+s+3)$。
扰动到第二比较点的合成项为 $[1+KG_1/(s+2)]N$，令其恒零即得补偿器。主导复极点实部为 $-0.5$，5%工程估算为 $3/0.5=6$ 秒。时间常数形式的外环乘积为 $20K/[s(s+2)(s+4)]=2.5K/[s(0.5s+1)(0.25s+1)]$，故应区分题中的放大器参数 $K$ 与整个开环增益。''','时域分析 / 主导极点')
a(24,'中国矿业大学','77','155–157',r'系统满足 $E=R-2C$、$C=(G_1E-2C)/(s+1)$。$G_1$ 的单位阶跃响应为 $(47/2)(1-e^{-2t})$。零初值。（1）$r=2\,1(t)$，求 $c(t)$；（2）求峰值时间及5%调节时间工程值；（3）求输出端跟踪误差 $r-c$ 的稳态值。',
 r'''$$c(t)=\frac{47}{50}\left[1-e^{-5t/2}\left(\cos\frac{5\sqrt{15}t}2+\frac1{\sqrt{15}}\sin\frac{5\sqrt{15}t}2\right)\right].$$
$t_p=2\pi/(5\sqrt{15})\approx0.3245\,\mathrm s$，$t_s\approx1.2\,\mathrm s$；输出端稳态误差 $53/50=1.06$。''',
 r'由阶跃响应得 $G_1=47/(s+2)$。局部反馈2使后一级成为 $1/(s+3)$，外反馈仍为2，因此 $\Phi=47/[(s+2)(s+3)+94]=47/(s^2+5s+100)$。其自然频率10、阻尼比0.25，单位幅值归一响应乘终值 $2\Phi(0)=0.94$ 即得第一式。阻尼振荡频率 $5\sqrt{15}/2$，据此求峰值与工程调节时间。输出端误差为 $2-0.94=1.06$，比较点误差则为 $2-2(0.94)=0.12$，两者不可混淆。','时域分析 / 二阶性能')
a(25,'中国海洋大学','78','157–159',r'系统满足 $E=R-2.5Y$、$Y=[K E/(0.05s+1)-N]/(s+1)$。$R=0,n=2\,1(t)$。（1）$K=40$，求比较点误差和输出稳态值；（2）改取 $K=20$，在扰动点之前前向通道再串联 $1/s$，先判稳，再讨论误差与输出；（3）如何降低扰动误差？',
 r'（1）$y(\infty)=-2/101$，$e(\infty)=5/101$；（2）闭环不稳定，不能给出实际稳态误差或输出；（3）须在稳定条件下提高低频环路增益或引入可实现的补偿。',
 r'''第一问扰动通道 $Y/N=-(0.05s+1)/[(0.05s+1)(s+1)+2.5K]$。二阶分母系数均正，闭环稳定。置 $s=0$ 再乘扰动幅度2，得到 $y=-2/(1+2.5K)$，$e=-2.5y$。
加入积分器后特征式为 $0.05s^3+1.05s^2+s+2.5K$。三阶劳斯条件 $1.05>0.125K$ 给出 $0<K<8.4$。题取 $K=20$ 不满足，出现右半平面极点；形式上的“积分使阶跃扰动误差为零”在本参数下无效。若另选 $0<K<8.4$，该积分结构可使所给阶跃扰动的比较点误差及输出终值归零。''','时域分析 / 稳态误差','答案册忽略新增积分器后的稳定性；8月勘误未列此项，本卡补入劳斯检验。')
a(26,'中南大学','78','159–160',r'外单位负反馈，系统 $C=2[K_1(R-C)-K_2sC]/[s(0.5s+0.4)]$，$K_1,K_2>0$。（1）$K_1=1,K_2=1.05$，求单位阶跃响应；（2）要求闭环复极点在单位圆上且 $\zeta=0.5$，求参数和峰值时间。',
 r'（1）$c=1-\frac43e^{-t}+\frac13e^{-4t}$；（2）$K_1=0.25,K_2=0.05$，$t_p=2\pi/\sqrt3$。',
 r'标准化闭环函数为 $4K_1/[s^2+(0.8+4K_2)s+4K_1]$。第一问分母 $s^2+5s+4=(s+1)(s+4)$，分解阶跃输出得结果。第二问复极点模长等于 $\omega_n$，单位圆要求 $\omega_n=1$，故 $4K_1=1$；再由 $2\zeta\omega_n=0.8+4K_2=1$ 得 $K_2=0.05$。$\omega_d=\sqrt3/2$，所以峰值时间为 $2\pi/\sqrt3$。','时域分析 / 二阶性能')
a(27,'哈尔滨工程大学','79','160–162',r'系统 $C=K[R-C-asC]/[s(s+2)]$。（1）要求 $\zeta=0.7$、单位斜坡误差0.25，求 $K,a$；（2）要求闭环复极点位于左半平面闭区域 $1\le|s|\le2$ 且与负实轴的夹角为 $30^\circ$ 到 $60^\circ$，求 $K,a$ 的范围。',
 r'（1）$K=31.36,a=73/392$；（2）$1\le K\le4$，$\sqrt K\le2+aK\le\sqrt{3K}$。',
 r'闭环分母为 $s^2+(2+aK)s+K$，故 $\omega_n=\sqrt K$、$\zeta=(2+aK)/(2\sqrt K)$，单位斜坡误差为 $(2+aK)/K$。第一问先由 $2\zeta/\omega_n=0.25$ 得 $\omega_n=5.6$。第二问环形区域给 $1\le\omega_n\le2$，角度区域给 $1/2\le\zeta\le\sqrt3/2$。代入两参数关系得答案，亦可将 $a$ 写成 $1/\sqrt K-2/K\le a\le\sqrt3/\sqrt K-2/K$。','时域分析 / 二阶性能')
a(28,'中山大学','79','162–163',r'单位负反馈开环 $G=T/(s^3+25s^2+4s)$。（1）求闭环稳定时 $T$ 的范围；（2）是否存在 $T$ 使全部闭环根均位于 $s=-1$ 左侧？',
 r'（1）$0<T<100$；（2）不存在。',r'闭环分母 $D=s^3+25s^2+4s+T$，三阶劳斯条件为 $T>0$、$25\times4>T$，得稳定区。若要求根实部小于 $-1$，令 $s=z-1$，有 $D(z-1)=z^3+22z^2-43z+T+20$。Hurwitz 多项式的系数必须同号，但一次项恒为负，所以无论 $T$ 如何取值都不满足。','时域分析 / 劳斯稳定')
rr,count=routh([1,2,2,4,3,6]);assert count==2
a(29,'中山大学','80','163–164',r'特征多项式 $D=s^5+2s^4+2s^3+4s^2+3s+6$，用劳斯判据判稳。',
 '不稳定，有2个右半平面根。',rr+r'\n\n可另行分解为 $(s+2)(s^4+2s^2+3)$。后一个偶多项式的根关于虚轴对称；$s^2=-1\pm j\sqrt2$ 并非负实数，因此其四根中有两个在右半平面，不能把出现全零行误判成全部为虚根。','时域分析 / 劳斯稳定')
a(30,'重庆大学','80','164–166',r'系统节点定义为 $E=R-V$、$U=KE-T_dV$、$X=U/s$、$V=X-C$、$C=V/(s+1)$，零初值。（1）求 $C/R,E/R$；（2）单位阶跃比较点稳态误差0.5，闭环自然频率 $\omega_n=2$，求 $K,T_d$，并求超调量与5%调节时间。',
 r'''令 $D=s^2+(2+K+T_d)s+K+T_d$，
$$\frac CR=\frac K D,\quad\frac ER=\frac{s^2+(2+T_d)s+T_d}D.$$
$K=T_d=2$，无超调，5%调节时间约 $4.13\,\mathrm s$。''',
 r'''由 $X=V+C=(s+2)V/(s+1)$，与 $sX=KR-(K+T_d)V$ 联立得两传递函数。阶跃比较点误差为 $T_d/(K+T_d)=0.5$，所以 $T_d=K$。自然频率平方为 $K+T_d=4$，故两者均为2。
闭环为 $2/(s^2+6s+4)$，阻尼比 $6/(2\cdot2)=1.5>1$，不能套欠阻尼超调或调节公式。终值为0.5，归一后的剩余误差为
$$q(t)=\frac{3+\sqrt5}{2\sqrt5}e^{-(3-\sqrt5)t}-\frac{3-\sqrt5}{2\sqrt5}e^{-(3+\sqrt5)t}.$$
它单调下降，解 $q(t_s)=0.05$ 得约4.13秒，超调为零。''','时域分析 / 二阶性能')
a(31,'上海交通大学（862）','81','166–168',r'系统满足 $E=R-C$、$U=(K/s)(E-\beta sZ)$、$Z=(U-GN)/s$、$C=Z+N$。（1）$N=0$ 时要求 $\zeta=0.8,\omega_n=2$，求 $K,\beta$、超调量和2%调节时间工程值；（2）求消扰的 $G(s)$。',
 r'$K=4,\beta=0.8$；$\sigma=e^{-4\pi/3}\approx1.516\%$，$t_s\approx2.5\,\mathrm s$；$G=s+3.2$。',
 r'消元得 $(s^2+K\beta s+K)Z=KR-KN-sGN$，再加上 $C=Z+N$。无扰动时分母与标准二阶式比较得 $K=4,K\beta=3.2$。扰动分子为 $s^2+K\beta s-sG$，使它恒为零要求 $G=s+K\beta$。补偿包括微分与比例项。超调和工程调节时间按题给阻尼比、自然频率计算。','校正 / 前馈')
a(32,'上海交通大学（862）','81','168–170',r'外单位负反馈，误差经 $1+1/s$，再减去测速反馈 $KsC$，之后经 $5/[s(s+1)]$ 输出。（1）求稳定的 $K$；（2）是否可使全部根实部小于 $-1$；（3）$r=(0.1t^2+2t+2)1(t)$，求 $e_{ss}\le0.1$ 的稳定参数范围。',
 r'（1）$K>0$；（2）不能；（3）$0<K\le0.3$。',
 r'''闭环特征式为 $D=s^3+(1+5K)s^2+5s+5$，三阶劳斯条件给 $K>0$。令 $s=z-1$，移轴后为
$$z^3+(5K-2)z^2+(6-10K)z+5K.$$
若稳定，需 $(5K-2)(6-10K)>5K$，即 $50K^2-45K+12<0$，但判别式 $45^2-4\cdot50\cdot12<0$，无解。
闭合测速内环后外开环为 $5(s+1)/[s^2(s+1+5K)]$，$K_a=5/(1+5K)$。阶跃与斜坡分量误差为零，二次项加速度为0.2，故 $e_{ss}=0.04(1+5K)$。解不等式并与稳定区相交得答案。''','时域分析 / 劳斯稳定')
a(33,'沈阳理工大学','82','170–171',r'单位负反馈 $G=100/[s(0.1s+1)]$，输入 $r=(1+t+at^2)1(t)$，$a\ge0$。求实际稳态误差。',
 r'$a=0$ 时 $e_{ss}=0.01$；$a>0$ 时误差无有限稳态值且向正无穷增长。',r'闭环分母 $0.1s^2+s+100$ 稳定。系统 I 型，$K_v=100$、$K_a=0$。阶跃分量无误差，单位斜坡贡献0.01；若 $a>0$，非零二次输入超出I型系统有限误差跟踪能力，误差含增长项，不能仍给0.01。','时域分析 / 稳态误差')
a(34,'沈阳理工大学','82','171',r'单位负反馈 $G=1/[s(s+1)]$，求零初值单位阶跃的首次达到终值上升时间、峰值时间及5%调节时间工程值。',
 r'$t_r=4\pi/(3\sqrt3)\approx2.418\,\mathrm s$，$t_p=2\pi/\sqrt3\approx3.628\,\mathrm s$，$t_s\approx6\,\mathrm s$。',r'闭环 $1/(s^2+s+1)$，$\omega_n=1,\zeta=0.5,\omega_d=\sqrt3/2$，$\arccos\zeta=\pi/3$。首次达到终值的上升时间 $(\pi-\pi/3)/\omega_d$，峰值时间 $\pi/\omega_d$，5%工程调节时间 $3/(\zeta\omega_n)$。这里上升时间采用0到100%定义，调节时间明确为工程估算。','时域分析 / 二阶性能')
a(35,'武汉科技大学','82','171–172',r'系统 $E=R-C$、$C=G_2[G_1(E+G_nN)+K_3N]$，$G_1=K_1/(T_1s+1)$、$G_2=K_2/[s(T_2s+1)]$。参数均正、闭环稳定。设计 $G_n$ 使阶跃扰动的稳态输出为零，并给出全过程完全补偿的形式解。',
 r'稳态补偿只需 $G_n(0)=-K_3/K_1$；最简单取常数 $-K_3/K_1$。全过程理想补偿为 $G_n=-K_3(T_1s+1)/K_1$。',r'扰动通道为 $C/N=G_2(G_1G_n+K_3)/(1+G_1G_2)$。因 $G_2$ 在原点含积分器，零频极限为 $G_n(0)+K_3/K_1$，所以常值阶跃的稳态抵消只约束补偿器的零频值。若要求所有时刻均无扰动输出，则需恒等式 $G_1G_n+K_3\equiv0$，得到含微分的形式逆补偿器。稳态补偿与全过程完全补偿是不同要求。','校正 / 前馈')

a(36,'清华大学','83','174–175',r'外单位负反馈，比例增益40，其后以正号叠加扰动，再经 $P=10(0.5s+1)/[s(s^2+20s+100)]$ 输出。输入 $\theta_i=0.2t1(t)$，扰动 $n=-2\,1(t)$，求 $e=\theta_i-\theta_o$ 的稳态值。',
 r'$e_{ss}=0.1$。',r'闭环分母为 $s^3+20s^2+300s+400$，三阶劳斯条件 $20\times300>400$ 成立。误差分解为 $E=R/(1+40P)-PN/(1+40P)$。参考斜坡的速度系数为 $\lim s40P=4$，贡献 $0.2/4=0.05$；扰动通道低频为 $-1/40$，负阶跃幅度为-2，贡献 $(-1/40)(-2)=0.05$。线性相加得0.1。','时域分析 / 稳态误差')
a(37,'清华大学','83','175–176',r'单位负反馈开环 $G=10000/[(s^2+10s+100)(s+50)]$，输入单位阶跃。（1）断开反馈时输出终值；（2）断开反馈时首次达到终值95%的时刻，并给主导二阶5%调节时间工程估算；（3）闭合反馈时的输出终值。',
 r'（1）2；（2）完整三阶模型首次达到95%约0.2479秒，5%工程调节时间约0.6秒；（3）$2/3$。',
 r'开环函数本身极点均在左半平面，故断开反馈时终值为 $G(0)=2$。快极点 $-50$ 近似忽略后，$G_{red}=200/(s^2+10s+100)$，$\omega_n=10,\zeta=0.5$，5%工程调节时间 $3/(\zeta\omega_n)=0.6$ 秒。首次达到95%与进入后不再离开5%误差带是不同事件：对原三阶响应求解 $c(t)=1.9$ 的第一个正根为0.2479秒；原三阶最后进入5%带约0.5495秒。闭环分母 $s^3+60s^2+600s+15000$ 稳定，闭环直流增益 $2/(1+2)=2/3$。','时域分析 / 主导极点','将题本“达到95%”与答案册采用的“5%调节时间”明确区分，并同时提供。')
a(38,'山东大学','84','176–178',r'系统 $C=G_0(G_1R-C)-N$，$G_0=K_0/[s(0.2s+1)(0.05s+1)]$，$G_1=K_1s+1$。误差为 $R-C$，$K_0>0$，$K_1$ 允许为实数。求参数，使（1）仅 $r=t1(t)$ 时 $e_{ss}=1$；（2）仅 $n=(1+t)1(t)$ 时 $e_{ss,N}\le0.05$，并保证闭环稳定。',
 r'$20\le K_0<25$，$K_1=1/K_0-1$。',r'前置 $G_1$ 不进入环路特征式。闭环分母为 $0.01s^3+0.25s^2+s+K_0$，劳斯条件给 $0<K_0<25$。参考误差通道为 $[1+G_0(1-G_1)]/(1+G_0)$，低频一阶项为 $(1/K_0-K_1)s$，单位斜坡终值因此为 $1/K_0-K_1=1$。扰动在输出以负号叠加，误差通道为 $1/(1+G_0)$，单位阶跃分量误差零，单位斜坡分量误差 $1/K_0\le0.05$，所以 $K_0\ge20$。','时域分析 / 稳态误差')
a(39,'陕西科技大学','84','178',r'闭环 $\Phi=35/[(s+1)(s^2+12s+35)]$。（1）按主导极点降阶；（2）求降阶单位阶跃响应；（3）用10%到90%上升时间和5%调节时间比较原模型与降阶模型。',
 r'（1）$\Phi_{red}=1/(s+1)$；（2）$c_{red}=1-e^{-t}$；（3）原模型两项时间均更长，约为 $2.3080,3.3730$ 秒；降阶模型约为 $2.1972,2.9957$ 秒。',
 r'原分母为 $(s+1)(s+5)(s+7)$，保留慢极点 $-1$ 并保持直流增益1，得到降阶函数。原精确阶跃响应为 $c=1-(35/24)e^{-t}+(7/8)e^{-5t}-(5/12)e^{-7t}$。分别解 $c=0.1,0.9,0.95$，得到上述数值。原系统等于一阶慢环节再串联两个正的快惯性环节，会引入额外延迟，不能仅因两个极点很快就断言原响应比降阶响应更快。','时域分析 / 主导极点','8月勘误未列此项；按完整响应修正答案册中原模型更快的判断。')
a(40,'陕西科技大学','85','178–179',r'两个单位负反馈系统的开环分别为 $G_1=1/(10s+10)$ 与 $G_2=10/(s+10)$。零初值单位阶跃，均按相对于各自终值的5%误差带，求精确调节时间及 $3T$ 工程值。',
 r'$t_{s1}=10\ln20/11\approx2.7234$ 秒，$t_{s2}=\ln20/20\approx0.1498$ 秒；工程值分别为 $30/11$ 与0.15秒。',r'应先闭合反馈。两闭环函数为 $1/(10s+11)$ 与 $10/(s+20)$，其时间常数分别 $10/11$ 与 $1/20$。对单调一阶响应，精确5%调节时间为 $T\ln20$。若直接按给定开环分母读取时间常数，会忽略反馈使极点移动。','时域分析 / 一阶响应','按答案册采用的单位负反馈约定补入题干，避免“开环传递函数”与调节时间所指模型不明。')
a(41,'深圳大学','85','179–180',r'单位负反馈 $G=(s+2)(s+6)/[s(s+3)(s+4)]$。（1）判稳；（2）求 $r=1(t)$、$r=2t1(t)$、$r=2t^2 1(t)$ 各自稳态误差。',
 r'闭环稳定；三项依次为 $0,2,+\infty$（第三项无有限稳态误差）。',r'特征多项式为 $s^3+8s^2+20s+12$，劳斯首列 $1,8,37/2,12$ 全正。系统为I型，$K_p=\infty$、$K_v=\lim sG=12/12=1$、$K_a=0$。因此阶跃无差，斜率2的斜坡误差为 $2/K_v=2$，非零二次输入产生增长误差。','时域分析 / 稳态误差','落实8月勘误第3页：分析题41斜坡误差由答案册的1更正为2。')
a(42,'深圳大学','85–86','180–182',r'原闭环 $\Phi=2/(s^2+2s+2)$。（1）求峰值时间、超调量及5%调节时间；（2）分别改成 $\Phi_1=(5s+1)\Phi$、$\Phi_2=\Phi/(s+5)$，按各自终值的5%带比较；（3）设计单位负反馈二阶系统，使相对超调量不变、峰值及调节时间均减半。',
 r'''各完整模型的精确指标为：

|模型|峰值时间/秒|相对超调|5%调节时间/秒|
|---|---:|---:|---:|
|原系统|3.1416|4.321%|2.0717|
|增加零点 $\Phi_1$|0.8961|261.361%|5.1460|
|增加极点 $\Phi_2$|3.3866|4.102%|2.3047|

（3）开环 $G_{new}=8/[s(s+4)]$。原系统调节时间的常用工程估算另为3秒。''',
 r'''原系统 $\zeta=1/\sqrt2,\omega_n=\sqrt2,\omega_d=1$，精确阶跃响应 $c_0=1-e^{-t}(\cos t+\sin t)$。其超调小于5%，所以5%调节时间是首次达到0.95的时刻，而不是粗略的3秒。
增加零点后的响应为 $c_1=c_0+5\dot c_0=1+e^{-t}(9\sin t-\cos t)$，导数为 $e^{-t}(10\cos t-8\sin t)$，首峰在 $\arctan(5/4)$。其余误差带交点可直接求根；零点没有改变原极点，不能称作“阻尼比下降”，但显著改变留数并延长调节时间。
增加极点后终值为0.2，须按该终值归一后计算5%误差带。对有理阶跃响应作部分分式、求导和最后误差带交点，得到表中数值。
第三问保持阻尼比不变、自然频率加倍，则 $\Phi_{new}=8/(s^2+4s+8)=\Phi(s/2)$，整个响应时间轴缩短为一半，包括精确调节时间；由 $G=\Phi_{new}/(1-\Phi_{new})$ 得开环。''','时域分析 / 二阶性能','完整响应复算修正答案册关于增加零点会缩短调节时间的泛化结论。')
a(43,'苏州大学','86','182–183',r'前向 $G=50/[s(0.1s+1)]$，反馈 $H=1/(s+5)$，比较点误差 $E=R-HC$。输入 $r=(2+2t+t^2)1(t)$，求误差的稳态性质。',
 '误差无有限终值，渐近为 $e(t)=0.2t+0.24+o(1)$。',r'特征多项式为 $s(s+10)(s+5)+500=s^3+15s^2+50s+500$，满足 $15\times50>500$，闭环稳定。比较点误差通道 $S=1/(1+GH)$ 为I型灵敏度函数，低频展开 $S=0.1s+0.02s^2+O(s^3)$。与 $R=2/s+2/s^2+2/s^3$ 相乘，得到 $E=0.2/s^2+0.24/s+$ 稳定衰减项，因此误差线性增长。非单位反馈时必须先明确比较点误差，不能直接将 $R-C$ 当作同一信号。','时域分析 / 稳态误差')
rr,count=routh([1,1,5,5,6,6]);assert count==0
a(44,'苏州大学','86','183–184',r'闭环特征多项式 $s^5+s^4+5s^3+5s^2+6s+6$。求右半平面根数及虚轴根。',
 r'右半平面根0个；虚轴根为 $\pm j\sqrt2,\pm j\sqrt3$；另一个根为 $-1$。',rr+r'\n\n也可分解 $D=(s+1)(s^4+5s^2+6)=(s+1)(s^2+2)(s^2+3)$。四个简单虚轴根产生不衰减振荡，因此不是渐近稳定。','时域分析 / 劳斯稳定')
a(45,'太原理工大学','87','184–185',r'无零点典型二阶单位负反馈系统，单位阶跃终值1，首峰1.3，峰值时间0.1秒。（1）求闭环与开环传递函数；（2）求单位斜坡稳态误差。以图示超调30%和峰值时间为准。',
 r'''令 $a=-\ln(0.3)/0.1$、$b=10\pi$、$w^2=a^2+b^2$，
$$\Phi=\frac{w^2}{s^2+2as+w^2},\quad G=\frac{w^2}{s(s+2a)}.$$
数值约 $G=1131.9155/[s(s+24.07946)]$，$e_{ss}\approx0.0212732$。''',
 r'由超调量 $0.3=e^{-\pi\zeta/\sqrt{1-\zeta^2}}=e^{-at_p}$，得到衰减率 $a=-\ln0.3/0.1$；峰值时间给阻尼振荡频率 $b=\pi/0.1$。因此自然频率平方为 $a^2+b^2$，无需使用图旁不一致的近似提示。开环速度系数 $K_v=w^2/(2a)$，单位斜坡误差为 $2a/w^2$。可回代 $e^{-a(0.1)}=0.3$ 检查图示数据。','时域分析 / 反求参数','题图旁指数近似提示与30%超调不一致，按图中可直接读出的峰值和时间独立反求；8月勘误未列此项。')
a(46,'天津工业大学','87','185–187',r'系统 $E=R-KC$、$C=2(E-\alpha sC)/(s^2+4s)$。本题统一采用教材5%调节时间工程式 $t_s\approx3.5/(\zeta\omega_n)$。（1）$K=8,\zeta=0.75$，求 $\alpha,t_s$ 和单位阶跃输出终值；（2）$t_s=0.875$ 秒、单位斜坡比较点误差0.25，求 $\alpha,K,\zeta$。',
 r'（1）$\alpha=1,t_s\approx7/6$ 秒，$c(\infty)=1/8$；（2）$\alpha=2,K=16,\zeta=1/\sqrt2$。',r'闭环分母 $s^2+(4+2\alpha)s+2K$，因此 $\omega_n=\sqrt{2K}$、$\zeta\omega_n=2+\alpha$。第一问 $\omega_n=4$，乘积为3，得 $\alpha=1$；输出直流增益为 $2/(2K)=1/K$。比较点误差对单位斜坡的终值为 $(4+2\alpha)/(2K)=(2+\alpha)/K$。第二问由 $3.5/(2+\alpha)=0.875$ 得 $\alpha=2$，再由 $4/K=0.25$ 得 $K=16$，最后计算阻尼比。','时域分析 / 二阶性能','将答案册本题采用的3.5工程系数写入题干；该近似与其他题注明的3系数或精确误差带解法区分。')
a(47,'同济大学','88','187–188',r'单位负反馈 $G=K/[s(s+p)]$。以下两问分别独立取参数：（1）单位阶跃误差 $e=2e^{-t}-e^{-2t}$，求 $K,p$；（2）峰值时间 $\pi/4$，相对超调 $e^{-3\pi/4}$，求 $K,p$。',
 r'（1）$K=2,p=3$；（2）$K=25,p=6$。',r'第一问 $E=2/(s+1)-1/(s+2)=(s+3)/(s^2+3s+2)$，而单位阶跃误差为 $(s+p)/(s^2+ps+K)$，比较得参数。第二问 $\omega_d=4$，超调指数给 $\zeta\omega_n=3$，故 $\omega_n^2=3^2+4^2=25$，$K=25$、$p=2\zeta\omega_n=6$。','时域分析 / 反求参数')
a(48,'同济大学','88','189',r'单位负反馈开环 $G=K(s+2)/[s(s^2+6s+10)]$。（1）用劳斯判据求稳定范围；（2）稳定时单位斜坡误差。',
 r'$K>0$，$e_{ss}=5/K$。',r'闭环分母 $s^3+6s^2+(10+K)s+2K$。三阶首列条件为 $K>0$、$10+K>0$、$6(10+K)>2K$；在 $K>0$ 时其余两条自动成立。速度系数 $K_v=2K/10=K/5$，故单位斜坡误差为5/K。','时域分析 / 劳斯稳定')
a(49,'武汉理工大学','89','189–191',r'单位负反馈误差 $E=R-C$，误差经 $(s+a)/(s+1)$，再减去扰动 $N$，然后经 $K/[s(s+1)(s+2)]$ 输出，$K,a>0$。求同时保证稳定、且单位斜坡参考与单位阶跃扰动共同作用时 $e_{ss}\le0.3$ 的参数约束，并判断是否存在解。',
 '不存在同时满足两个要求的正参数。',r'''闭环分母为 $D=s^4+4s^3+5s^2+(2+K)s+aK$。劳斯条件为
$$0<K<18,\qquad 0<a<\frac{(18-K)(K+2)}{16K}.$$
参考斜坡贡献 $2/(aK)$，扰动在对象输入以负号注入，误差贡献为 $1/a$，两者同号，所以
$$e_{ss}=\frac{K+2}{aK}\le0.3\ \Longrightarrow\ a\ge\frac{10(K+2)}{3K}.$$
若两边界能相容，须 $10/3<(18-K)/16$，即 $K<-106/3$，与 $K>0$ 矛盾。因此不能只列一组互不相容的不等式就称设计完成。''','时域分析 / 稳态误差')
a(50,'武汉理工大学','89','191–192',r'系统 $C=[R-C-KsC]/[s(s+1)]$。（1）要求阻尼比0.6，求 $K$；（2）求上升时间、峰值时间、超调量及5%调节时间工程值；（3）简述速度反馈的优缺点。',
 r'$K=0.2$，$t_r=(\pi-\arccos0.6)/0.8\approx2.768$ 秒，$t_p=\pi/0.8\approx3.927$ 秒，$\sigma\approx9.478\%$，$t_s\approx5$ 秒。',r'闭环分母 $s^2+(1+K)s+1$，自然频率1、阻尼比 $(1+K)/2$。代入0.6得增益0.2，阻尼振荡频率0.8，据典型二阶公式求指标。速度反馈可增加阻尼、降低超调，但过强可导致过阻尼而变慢；本结构外环速度系数从1降为 $1/(1+K)$，单位斜坡误差增至 $1+K$。测速噪声和微分实现也是实际代价，不能只说反馈必然改善全部性能。','时域分析 / 二阶性能')
a(51,'西安邮电大学','90','192–194',r'系统 $E=R-5C$、$C=(2/s)(G_1E-2C)$，$G_1$ 的零初值单位阶跃响应为 $(8/5)(1-e^{-5t})$。输入 $r=20\,1(t)$，求输出终值、2%调节时间工程值，并分别求比较点误差与输出端跟踪误差的终值。',
 r'$c(\infty)=3.2$，$t_s\approx8/9$ 秒；比较点误差为4，输出端跟踪误差为16.8。',r'$G_1=8/(s+5)$。内环合并得到后级 $2/(s+4)$，外反馈5给 $\Phi=16/[(s+5)(s+4)+80]=16/(s^2+9s+100)$。故自然频率10、阻尼比0.45，终值 $20\Phi(0)=3.2$。2%工程时间为 $4/4.5=8/9$ 秒。比较点误差 $20-5(3.2)=4$，跟踪误差 $20-3.2=16.8$。题图反馈为5，必须按非单位反馈计算。','时域分析 / 二阶性能')
a(52,'西安交通大学','90','194–195',r'闭环 $G=[(s^2+2s+2.21)(s+10)]/[(s^2+2s+2)(s+2)(s+11.05)]$。求单位阶跃的最大相对超调与2%调节时间，以及单位斜坡响应。给近邻零极点降阶近似，并与完整模型区分。',
 r'''完整模型：超调约 $0.2313\%$，2%调节时间约 $2.3860$ 秒。单位斜坡响应为
$$\begin{aligned}c_r(t)={}&\frac t2-\frac{647}{2210}+\frac{221}{905}e^{-2t}\\
&+\frac{21e^{-t}}{408010}(925\cos t+904\sin t)\\
&+\frac{1554000}{1632080801}e^{-221t/20},\quad t\ge0.\end{aligned}$$
降阶 $G_{red}=1/(s+2)$，其阶跃无超调，2%精确调节时间 $\ln50/2\approx1.9560$ 秒，工程值2秒；斜坡响应 $t/2-1/4+e^{-2t}/4$。''',
 r'两对近邻复零极点及一对高频实零极点可近似相消，保持直流增益0.5后得到一阶近似。但这些零极点没有精确相消，原模型仍有小振荡尾部，不能把近似模型的“无超调”当作原系统的精确结论。对原 $G/s$ 作部分分式，令导数为零求首个全局峰值，得到约 $t_p=4.0444$ 秒及0.2313%超调；求最后一次达到终值0.5的2%误差带交点，得2.3860秒。对 $G/s^2$ 分解并反变换得上述斜坡响应，渐近斜率0.5、截距 $-647/2210$，与低频 $G(0),G\prime(0)$ 一致。','时域分析 / 主导极点')

a(53,'长安大学','91','195–197',r'系统 $E=R-C$、$U=(K_r/s)(E-KsC)+K_vR$、$C=U/s$，参数正。$K_v=0$ 时，单位阶跃超调16.3%（按 $\zeta=0.5$），单位斜坡稳态误差0.25。（1）求 $K_r,K$；（2）设计 $K_v$ 使单位斜坡无差。',
 r'$K_r=16,K=0.25$；取 $K_v=4$。',r'闭环函数 $\Phi=(K_r+K_vs)/(s^2+K_rKs+K_r)$。$K_v=0$ 时自然频率 $\sqrt{K_r}$、阻尼比 $K\sqrt{K_r}/2$，而单位斜坡误差为 $K$。所以 $K=0.25$，$0.5=0.25\sqrt{K_r}/2$ 得 $K_r=16$。加入前馈后，误差低频系数为 $(K_rK-K_v)/K_r$，令它为零得 $K_v=K_rK=4$。前馈改变分子而不改变闭环稳定的特征式。','时域分析 / 反求参数')
a(54,'长沙理工大学','91–92','197–198',r'系统按以下完整连接定义：$E=R+HN-C$，$X=G_2(E+G_1R)+N$，$C=G_4(X+G_3E)$。其中 $H$ 是从可测扰动 $N$ 到第一个比较点的待设计前馈环节。（1）求 $C/R$；（2）求使 $N$ 对 $C$ 完全无影响的 $H$。',
 r'''令 $D=1+(G_2+G_3)G_4$，
$$\frac CR=\frac{[G_2+G_3+G_1G_2]G_4}D,\quad H=-\frac1{G_2+G_3}.$$''',
 r'将输出式写为 $C=G_4[(G_2+G_3)E+G_1G_2R+N]$，再代入误差定义。参考分子为 $G_4(G_2+G_3+G_1G_2)$，扰动分子为 $G_4[1+H(G_2+G_3)]$，公共分母为 $D$。将扰动分子恒等置零，得到理想补偿。补偿器存在的前提是 $G_2+G_3$ 不恒零，且实际应用还须检查因果性和内部稳定性。','校正 / 前馈','题本询问H但原图相应扰动支路漏标H；按答案册的该支路定义在题干直接补齐。')
a(55,'长沙理工大学','92','198–199',r'单位负反馈系统零初值单位阶跃误差 $e(t)=1.4e^{-1.07t}-0.4e^{-3.73t}$，所给小数按精确值处理。求闭环传递函数、分母对应的 $\zeta,\omega_n$ 和阶跃稳态误差。',
 r'''$$\Phi=\frac{0.006s+3.9911}{s^2+4.8s+3.9911}.$$
$\omega_n=\sqrt{3.9911}\approx1.9978$，$\zeta=2.4/\sqrt{3.9911}\approx1.2013$，$e_{ss}=0$。''',
 r'误差变换 $E=1.4/(s+1.07)-0.4/(s+3.73)=(s+4.794)/[(s+1.07)(s+3.73)]$。所以闭环 $\Phi=1-sE$，分子为 $(4.8-4.794)s+3.9911$。微小的一次项0.006来自题给小数，不能在称为精确解时删去。两个极点均为负实数，响应最终误差为零；分母对应过阻尼，但含零点时动态指标不应全部套无零点典型模型。','时域分析 / 反求参数')
a(56,'河北工业大学','92','199–201',r'系统 $E=R-C$、$C=K_2[K_1E+sK_3R+N-\tau sC]/[s(Ts+1)]$。$K_1=1,2K_2=1,K_2K_3=1,T=0.25$。（1）$r=(1+2t)1(t),n=1(t)$，求稳态误差；（2）讨论测速参数 $\tau\ge0$ 的影响。',
 r'$e_{ss}=2\tau-1$。测速反馈提高阻尼，在稳定前提下本题总误差为零时取 $\tau=0.5$。',r'闭环分母 $D=0.25s^2+(1+0.5\tau)s+0.5$，对 $\tau\ge0$ 均稳定。参考误差通道为 $(0.25s^2+0.5\tau s)/D$，单位阶跃分量误差零，斜率2的斜坡贡献 $2\tau$。扰动误差通道为 $-0.5/D$，单位阶跃贡献-1，所以总和为 $2\tau-1$。自然频率不随 $\tau$ 变，阻尼随之增大；超过临界阻尼以后继续增大可能使慢极点接近原点，不能说调节时间始终缩短。','时域分析 / 稳态误差')
a(57,'北京信息科技大学','93','201–202',r'复合控制按题本乘积形式明确为 $G_1=K_1(T_1s+1)$、$G_2=K_2s(T_2s+1)$、$G_3=K_3K_2$，参数正。系统 $E=R-C$、$C=G_2[G_1(E+G_nN)+G_3N]$。求闭环稳定条件，并设计 $G_n$ 使单位阶跃扰动的稳态误差为零；另给全过程完全补偿。',
 r'稳定条件 $K_1K_2>T_1T_2/(T_1+T_2)$。任意零频有限的 $G_n$ 均使此阶跃扰动稳态误差为零，最简单为0；全过程补偿 $G_n=-K_3K_2/[K_1(T_1s+1)]$。',
 r'按题面写出的乘积，$G_2$ 在原点有零点。闭环特征式 $1+K_1K_2s(T_1s+1)(T_2s+1)$ 为三阶，劳斯条件整理为所列不等式。扰动通道 $C/N=G_2(G_1G_n+G_3)/(1+G_1G_2)$，若 $G_n$ 在原点有限，则零频值为零，故单位阶跃扰动输出及误差均趋零。若要求任意扰动全过程抵消，则必须令 $G_1G_n+G_3\equiv0$。题本这里写的是乘积，不能擅自改成积分环节再套另一套答案。','校正 / 前馈','题本G2的乘积记法与答案册推导存在不一致；按题本明确的乘积形式及图中正向补偿支路列方程，避免静默猜测分母。')
a(58,'北京信息科技大学','93','202–203',r'单位负反馈开环 $G=2/[s(s+3)]$。求零初值单位阶跃响应、超调及精确5%调节时间。',
 r'$c(t)=1-2e^{-t}+e^{-2t}$；无超调；$t_s=-\ln(1-\sqrt{0.95})\approx3.6761$ 秒。',r'闭环 $\Phi=2/[(s+1)(s+2)]$，分解 $\Phi/s=1/s-2/(s+1)+1/(s+2)$。响应可写成 $(1-e^{-t})^2$，对 $t\ge0$ 单调上升至1，故超调为零。相对误差为 $2e^{-t}-e^{-2t}$，置 $z=e^{-t}$，解 $2z-z^2=0.05$，取 $0<z<1$ 的根 $z=1-\sqrt{0.95}$。','时域分析 / 二阶性能')
a(59,'东北电力大学','94','203–205',r'系统 $E=R-C$，误差经 $(s+a)/s$，再以正号叠加扰动 $N$，之后经 $K(s+3)/(s^2-1)$ 输出，$K,a>0$。（1）求稳定条件；（2）稳定时 $r=t1(t),n=1(t)$，求总稳态误差。',
 r'稳定当且仅当 $(K-3)a+3K-1>0$（同时 $K,a>0$）；$e_{ss}=-1/(3Ka)$。',r'特征式为 $D=s^3+Ks^2+(Ka+3K-1)s+3Ka$。三阶劳斯条件可化为 $K(Ka+3K-1)>3Ka$，即所列条件，它也保证一次系数为正。参考单位斜坡的低频误差为 $-1/(3Ka)$，负号来自对象在零频的负增益。扰动位于PI控制器之后，误差通道低频为 $-1/G_c=-s/(s+a)$，对单位阶跃的终值为零。因此总误差只剩参考贡献，负稳态误差并非计算错误。','时域分析 / 劳斯稳定')
a(60,'福州大学','94','205–206',r'特征多项式 $D=s^5+8s^4+25s^3+40s^2+34s+12$，已知一根为 $-1$。求实部落在闭区间 $[-2,-1]$ 的闭环极点个数。',
 r'4 个，分别为 $-2,-1,-1+j,-1-j$。',r'试根并多项式除法得 $D=(s+1)(s+2)(s+3)(s^2+2s+2)$。二次因子的根为 $-1\pm j$，它们虽然不是实数，但实部也落在区间内。闭区间包括边界-2与-1，因此计入四个；如果只问“实根位于区间”才是两个。','时域分析 / 特征根')
a(61,'哈尔滨理工大学','94','206',r'特征多项式 $D=s^4+9s^3+31s^2+9s+20+K$。用劳斯判据求导致临界等幅振荡的 $K$ 和频率。',
 r'$K=10$，$\omega=1\,\mathrm{rad/s}$。',r'劳斯表前两行是 $(1,31,20+K)$、$(9,9,0)$，第三行首项30，第四行首项为 $(90-9K)/30$。出现临界全零行时 $K=10$，辅助多项式为 $30s^2+30$，给出虚根 $\pm j$。此时 $D=(s^2+1)(s^2+9s+30)$，另两根在左半平面，故为临界振荡。','时域分析 / 劳斯稳定')
a(62,'海南大学','95','206–207',r'单位负反馈开环 $G=50/[s(0.1s+1)(s+5)]$。（1）判稳；（2）输入 $r=(2+2t+t^2)1(t)$，求稳态误差性质；（3）如何减小或消除相应误差？',
 r'闭环稳定；误差无有限终值，渐近 $0.2t+0.24$。应在保持稳定的条件下提高型别或采用适当参考前馈。',r'闭环特征式可写成 $s^3+15s^2+50s+500$，满足三阶稳定条件。系统为I型，阶跃无差，斜率2的斜坡贡献0.2，而二次输入使误差增长。由灵敏度低频展开 $1/(1+G)=0.1s+0.02s^2+O(s^3)$，得到总误差渐近式。增加增益只能降低有限的低频误差系数，不能使I型对二次输入产生有限误差；增加积分器提高到II型后可得到有限二次误差，若要严格无差需更高阶内模或准确的前馈，并重新检查稳定性。','时域分析 / 稳态误差')
a(63,'华南理工大学','95','208–211',r'系统 $E=R-C$、$V=(K_2/s)(G_cE-G_fV)$、$C=(V+D)/s$，$K_2>0$。（1）$G_c=K_1>0,G_f=\eta\ge0$，分析 $\eta$ 从0增大时的稳定性、超调和调节时间；（2）$r=d=1(t)$，重新设计 $G_c,G_f$ 使稳态误差消除，并验证稳定。',
 r'（1）$\eta=0$ 无阻尼；$\eta>0$ 稳定，超调随阻尼增大而减小，过阻尼后调节可能变慢。（2）可取 $G_f=1,G_c=1+K_2/(2s)$，两种阶跃共同作用下误差终值0。',r'''第一问闭环分母为 $s^2+K_2\eta s+K_1K_2$，$\omega_n=\sqrt{K_1K_2}$、$\zeta=K_2\eta/(2\sqrt{K_1K_2})$。原点开始的 $\eta=0$ 有纯虚根，并非渐近稳定。进入欠阻尼区后超调减小；过阻尼时慢根趋近 $-K_1/\eta$，过大的速度反馈反而延长响应。
令 $G_f=\eta>0,G_c=k_p+k_i/s$，闭环特征式变为 $s^3+K_2\eta s^2+K_2k_ps+K_2k_i$。三阶稳定条件 $K_2\eta k_p>k_i>0$。所给设计取 $\eta=k_p=1,k_i=K_2/2$，严格满足。此时参考阶跃和输入到末级积分器的扰动阶跃，在误差通道内均具有零频零点，所以终值均为零。''','校正 / PID 控制')
a(64,'合肥工业大学','96','211–212',r'单位负反馈，误差经 $K/(2s+1)$，以正号叠加扰动 $D$，再经 $1/[(3s+1)(10s+1)]$ 输出，$K>0$。（1）求稳定范围；（2）$r=2\,1(t),d=-2\,1(t)$，要求总稳态误差0.4，求 $K$。',
 r'（1）$0<K<13$；（2）$K=9$。',r'特征式 $60s^3+56s^2+15s+1+K$，三阶劳斯条件 $56\times15>60(1+K)$ 给 $K<13$。阶跃参考误差为 $2/(1+K)$；扰动误差通道低频为 $-1/(1+K)$，幅值-2产生正误差 $2/(1+K)$。相加为 $4/(1+K)=0.4$，得 $K=9$，位于稳定区。','时域分析 / 稳态误差','落实8月勘误第4页：总误差更正为4/(1+K)，K=9；不沿用原答案的错误二次方程。')
a(65,'华东交通大学','96','213–214',r'系统 $C=10K[R-C-\tau sC]/[s(s+1)]$。（1）超调16.3%（按 $\zeta=0.5$）、峰值时间1秒，求 $K,\tau$；（2）$K=0.4,\tau=0.14$，求超调、峰值时间与精确5%调节时间，并给常用 $3/(\zeta\omega_n)$ 工程值。',
 r'（1）$K=2\pi^2/15$，$\tau=(2\pi/\sqrt3-1)/(4\pi^2/3)$；（2）超调26.432%，峰值1.7059秒，精确5%调节3.8437秒，工程估算3.8462秒。',r'闭环分母 $s^2+(1+10K\tau)s+10K$。第一问由 $\omega_d=\pi$、$\zeta=0.5$ 得 $\omega_n=2\pi/\sqrt3$，再比较系数求参数。第二问 $\omega_n=2,\zeta=0.39,\omega_d=\sqrt{3.3916}$，超调为 $\exp[-0.78\pi/\sqrt{3.3916}]$，峰值为 $\pi/\sqrt{3.3916}$。以标准阶跃响应的相对误差求最后一个 $\pm5\%$ 交点得3.8437秒。若采用答案册的3.5系数，工程估算会为4.4872秒，不能把不同工程系数所得值称为同一个精确时间。','时域分析 / 二阶性能')
a(66,'南京理工大学','97','215',r'无零点二阶单位负反馈系统，其零初值单位阶跃响应单调增长，并渐近于直线 $c(t)=t-1$。求闭环及开环传递函数，并说明此响应是否具有有限终值。',
 r'$\Phi=1/[s(s+1)]$，$G=1/(s^2+s-1)$；阶跃响应 $c=t-1+e^{-t}$，无有限终值。',r'零初值二阶无零点函数的斜直线渐近响应意味着闭环含原点极点。写 $\Phi=K/[s(s+a)]$，其阶跃响应为 $(K/a)t-K/a^2+(K/a^2)e^{-at}$。渐近斜率1、截距-1给 $K/a=1,K/a^2=1$，故 $K=a=1$。再由单位负反馈逆关系 $G=\Phi/(1-\Phi)$ 得开环。闭环含积分器，不能把图中持续增长的曲线误称为有稳态值的稳定阶跃响应。','时域分析 / 反求参数','题图的斜线及差值按渐近关系写清，避免将有限时刻的近似图示当成精确等式。')
a(67,'东华大学','97','216–218',r'无零点典型二阶单位负反馈系统，完整单位阶跃响应写为 $c=1-Ae^{-at}\sin(bt+\varphi)$。已知 $b=\sqrt3,\varphi=60^\circ$；在 $t_1$ 时指数包络系数 $Ae^{-at_1}=0.006$。（1）求阻尼比、自然频率、开闭环函数；（2）求 $t_1$，说明此时是否已进入且保持5%误差带；（3）求单位斜坡误差。',
 r'$\zeta=0.5,\omega_n=2$，$\Phi=4/(s^2+2s+4)$，$G=4/[s(s+2)]$；$t_1=\ln[2/(0.006\sqrt3)]\approx5.2598$ 秒；已保持在5%带内；斜坡误差0.5。',r'典型二阶相位 $\varphi=\arccos\zeta$，所以 $\zeta=0.5$。由 $b=\omega_n\sqrt{1-\zeta^2}=\sqrt3$ 得自然频率2、衰减率 $a=1$，包络系数 $A=1/\sqrt{1-\zeta^2}=2/\sqrt3$。解 $(2/\sqrt3)e^{-t_1}=0.006$ 得时间。此时包络已小于0.05且以后单调衰减，所以未来均保持在5%带内，不能只凭某一瞬间误差小就断言调节完成。$K_v=4/2=2$，斜坡误差1/2。','时域分析 / 反求参数','将原题单个时刻表达式所隐含的二阶振荡频率、相位和包络条件直接写入题干，使反求条件完整。')
a(68,'东华大学','98','218–220',r'交叉耦合结构明确为 $U=G_3(R-C)$、$X=G_1(-U+Y)$、$Y=G_2(U-X)$、$C=X+Y$。（1）求 $C/R$；（2）$G_1=1/s,G_2=1/(s+1),G_3=2$，求单位阶跃5%调节时间；（3）$G_1=2/s,G_2=1/(s+1),G_3=1/(s+2)$，求阶跃稳态误差。',
 r'''令 $P=G_2-G_1+2G_1G_2$，
$$\frac CR=\frac{G_3P}{1+G_1G_2+G_3P}.$$
（2）$\Phi=2/(s^2+s+3)$，精确5%调节约6.0132秒，工程估算6秒；（3）$\Phi=(2-s)/(s^3+3s^2+3s+6)$，$e_{ss}=2/3$。''',
 r'由两耦合方程得 $X=G_1(G_2-1)U/(1+G_1G_2)$、$Y=G_2(1+G_1)U/(1+G_1G_2)$，相加再闭合外环得到通式。第二问标准分母给 $\zeta\omega_n=0.5$，工程时间为6秒，完整误差带最后交点略有差异。第三问代入并通分，三阶分母满足 $3\times3>6$，稳定，直流增益1/3，所以阶跃误差2/3。交叉线路没有节点时不能相连，正负号须按所列方程。','时域分析 / 二阶性能')
a(69,'华东理工大学','98','220–222',r'单位反馈系统，反馈可能为正也可能为负。开环 $G=K^*/[(s^2+2s+2)(s^2+2s+5)]$，$K^*>0$。分别求两种极性的稳定范围，并求对两种极性都保证稳定的范围。',
 r'负反馈 $0<K^*<65/4$；正反馈 $0<K^*<10$；未知极性仍保证稳定需 $0<K^*<10$。',r'乘积分母为 $s^4+4s^3+11s^2+14s+10$。负反馈特征常数项为 $10+K^*$，劳斯第三行首项 $15/2$，下一行符号由 $65-4K^*$ 决定，得第一范围。正反馈常数项为 $10-K^*$，要求 $K^*<10$；其余劳斯条件在正增益下自动成立。未知极性须取两个稳定集合的交集。','时域分析 / 劳斯稳定')
a(70,'华东理工大学','99','222–224',r'前向 $G_1$ 的单位阶跃响应为 $(8/5)(1-e^{-5t})$，反馈 $G_2=10/(s+4)$。（1）$r=20\,1(t)$，求输出终值；（2）$r=10\,1(t)$，求相对超调、精确5%调节时间，并区分比较点误差 $r-G_2c$ 与跟踪误差 $r-c$。',
 r'（1）6.4；（2）超调约104.224%，5%调节约0.6963秒；比较点误差2，跟踪误差6.8。',r'由阶跃响应得 $G_1=8/(s+5)$，闭环 $\Phi=8(s+4)/(s^2+9s+100)$。它包含零点-4，不能只按分母的 $\zeta=0.45$ 套无零点超调公式。单位阶跃终值0.32，令 $b=\sqrt{319}/2$，完整响应为 $0.32[1-e^{-4.5t}(\cos bt-(20.5/b)\sin bt)]$。导数零点满足 $\tan bt=2b$，取首个正根求峰值，得104.224%。求相对终值最后一个5%交点得0.6963秒。比较点灵敏度的直流值为 $1/(1+G_1(0)G_2(0))=1/5$，故幅值10参考的比较点误差2；输出终值3.2，跟踪误差6.8。','时域分析 / 二阶性能')
a(71,'南京工业大学','99','224–225',r'位置控制系统：$E=R-C$，在 $K_1,K_2$ 之前减去速度反馈 $K_3sC$，随后依次经过 $K_1,K_2,1/(Is),1/s$ 得到位置 $C$，$I=25$，位移单位米。（1）单位斜坡 $r=t$ 的稳态误差需1厘米，求 $K_3$；（2）取该值，求使相对超调不超过10%的正参数 $K_1,K_2$ 条件。',
 r'$K_3=0.01$，$K_1K_2\ge10^6(\ln10)^2/[\pi^2+(\ln10)^2]\approx349464.274$。',r'令 $P=K_1K_2$，闭环分母为 $Is^2+PK_3s+P$。单位斜坡误差为 $K_3$ 米，1厘米即0.01米。标准二阶阻尼比 $\zeta=K_3\sqrt P/(2\sqrt I)$。10%超调要求 $\zeta\ge\ln10/\sqrt{\pi^2+(\ln10)^2}$；代入 $I=25,K_3=0.01$，平方整理得乘积下界。超过临界阻尼后无超调，同样包含在条件内。','时域分析 / 二阶性能')

a(72,'南京工业大学','100','226–227',r'副翼执行机构为 $G_a=1/s+0.5$，外单位负反馈，扰动在执行机构之后以正号叠加，飞机模型为 $10/[s(s+2)]$。（1）写执行机构传递函数；（2）求闭环函数；（3）$r=(1+t)1(t),n=0.2\,1(t)$，讨论误差是否有终值；（4）去掉执行机构中的积分支路，仅保留0.5，求阻尼比和自然频率。',
 r'$G_a=(0.5s+1)/s$，$\Phi=5/(s^2+5)$；第三问误差无有限终值；去掉积分后 $\zeta=1/\sqrt5,\omega_n=\sqrt5$。',r'闭环未约去前的特征式为 $s^3+2s^2+5s+10=(s+2)(s^2+5)$，参考通道可约去稳定因子 $s+2$，仍有简单虚轴极点 $\pm j\sqrt5$。所以阶跃及斜坡激起持续振荡，不能给实际稳态误差为零。去掉积分支路后，开环为 $5/[s(s+2)]$，闭环分母 $s^2+2s+5$，比较标准形式得到第四问参数。','时域分析 / 稳定性')
a(73,'南开大学（学硕）','101','227–228',r'以下两问分别属于不同系统。（1）零初值系统 $\ddot c+4\dot c+3c=r$，求传递函数；（2）系统 $\ddot c+3\dot c+2c=r$，$c(0^-)=1,\dot c(0^-)=0$，输入单位阶跃，求总响应。',
 r'（1）$C/R=1/(s^2+4s+3)$；（2）$c=1/2+e^{-t}-\tfrac12e^{-2t}$。',r'第一问零初值变换即可，传递函数本身不取决于本次输入是不是阶跃。第二问单边变换给 $(s^2+3s+2)C=1/s+s+3$。部分分式为 $C=1/(2s)+1/(s+1)-1/[2(s+2)]$。回代初值 $1/2+1-1/2=1$，初始导数 $-1+1=0$，最终值1/2，均满足运动方程。')
a(74,'南京理工大学','101','228–229',r'外单位负反馈，控制器 $K_c(Ts+1)$，对象 $1/s^2$；对象输入另以正号叠加 $K_sC$，参数均正。（1）求稳定条件；（2）$K_s=0.8$，要求单位阶跃相对超调 $e^{-1}$、精确5%调节时间0.8秒，求一组满足条件的参数。必须保留控制器所引入的闭环零点。',
 r'（1）$K_c>K_s$；（2）一组数值解为 $K_c\approx81.002668,T\approx0.08652843$。',r'''闭环函数
$$\Phi=\frac{K_c(Ts+1)}{s^2+K_cTs+K_c-K_s}.$$
正参数下二阶稳定等价于 $K_c>K_s$。分子含零点，不能用无零点典型二阶超调式直接反求参数。
令 $a=K_cT/2$、$b=\sqrt{K_c-K_s-a^2}$、$A=K_c/(K_c-K_s)$。归一阶跃误差为
$$q(t)=e^{-at}\left[\cos bt+\frac{a-K_cT/A}{b}\sin bt\right].$$
用响应导数为零确定首峰，使最大 $-q(t)$ 为 $e^{-1}$；再求 $|q|=0.05$ 的最后交点为0.8。带正参数约束数值求根得到所列解，回代超调36.787944%、调节0.800000秒。该解的极点约 $-3.50452\pm8.24142j$、终值约1.009975。''','时域分析 / 反求参数','原答案用无零点二阶近似求参数；此处题干明确保留零点及精确误差带，给出完整模型的一组数值解。')
a(75,'南京理工大学','102','229',r'无零点、I型的三阶单位负反馈系统，开环写为 $G=k/[s(s^2+as+b)]$。要求单位斜坡误差2.5，一对闭环极点为 $-2\pm2j$。求 $G$ 并检查第三个极点。',
 r'$G=4/[s(s^2+4.5s+10)]$，第三个闭环极点为 $-0.5$。',r'设第三个极点为 $-p$，闭环特征式为 $(s+p)(s^2+4s+8)$。与 $s^3+as^2+bs+k$ 比较，得 $a=p+4,b=4p+8,k=8p$。单位斜坡误差 $b/k=2.5$，所以 $(4p+8)/(8p)=2.5$，解得 $p=0.5$，再求其余参数。三根均在左半平面，稳态误差公式适用。','时域分析 / 反求参数','把答案册隐含的无零点I型模型假设直接写入题干，避免一般三阶传递函数的反求不唯一。')
a(76,'青岛科技大学','102','229–232',r'系统 $C=[72(R-C)-K_tsC]/[2s(s+2.4)]$。（1）无测速反馈时求 $\zeta,\omega_n$、超调、峰值时间与5%调节时间工程值；（2）令 $\zeta=0.7$，求 $K_t$ 和同样指标；（3）讨论测速反馈的影响。',
 r'（1）$\zeta=0.2,\omega_n=6$，超调约52.66%，$t_p\approx0.5344$ 秒，$t_s\approx2.5$ 秒；（2）$K_t=12$，超调约4.599%，$t_p\approx0.7332$ 秒，$t_s\approx0.7143$ 秒。',r'标准化分母 $s^2+(2.4+K_t/2)s+36$，所以自然频率恒为6，阻尼比为 $(2.4+K_t/2)/12$。无测速时为0.2；要求0.7得 $K_t=12$。分别用 $\sigma=e^{-\pi\zeta/\sqrt{1-\zeta^2}}$、$t_p=\pi/[6\sqrt{1-\zeta^2}]$ 计算。所列5%时间统一按 $3/(\zeta\omega_n)$ 估算。测速反馈减小超调，但峰值时间可能增大，且过强反馈造成过阻尼后不保证更快。','时域分析 / 二阶性能')
a(77,'广东工业大学','103','232–235',r'参考经 $2/(1+Ts)$ 后与输出作负反馈比较，经 $s+12$，再减去测速反馈 $KsC$，最后经 $1/[3s(s+1)]$ 输出。（1）$T=0$，以完整模型的单位阶跃相对超调9.5%确定 $K$，求闭环函数和极点；（2）求峰值、2%调节时间和终值，画响应；（3）保持该 $K$、令 $T=1$，求函数并比较响应。',
 r'''$K\approx3.22631342$，记 $d=4+K$，
$$\Phi_T=\frac{2(s+12)}{(1+Ts)(3s^2+ds+12)}.$$
$T=0$ 极点约 $-1.204386\pm1.596701j$；峰值时间1.87559秒，精确2%调节2.88608秒，终值2。
$T=1$ 新增极点-1，响应无正超调，精确2%调节约4.22372秒，终值仍为2。''',
 r'由原节点方程直接得到所列闭环函数，前置环节不进入反馈特征二次式。$T=0$ 时必须保留分子零点-12，按完整阶跃导数确定峰值，再以相对超调0.095求 $K$。首个全局峰值为2.19。使用无零点近似可得教材参数 $K\approx3.2$，但它并非完整模型严格满足9.5%的解。$T=1$ 时将原响应与单位时间常数的一阶核卷积，形成更慢的输出；按完整模型检查无超调，图中应表现这一点。','时域分析 / 二阶性能','区分答案册K=3.2的忽略零点近似与完整模型数值解，完整模型的响应图统一采用后者。')
a(78,'广东工业大学','103–104','235–236',r'基础反馈系统 $y=GK(r-y)+G_dd$。增加扰动前馈后为 $y=G[K(r-y)+K_dd]+G_dd$。（1）比较扰动抑制能力；（2）求理想完全补偿所需 $K_d$。',
 r'扰动通道分别为 $G_d/(1+GK)$ 和 $(G_d+GK_d)/(1+GK)$。准确且可实现的前馈取 $K_d=-G_d/G$ 时可完全抵消。',r'分别将输出项移到左边即可求两通道。前馈提供额外的设计自由度，但只有当 $G_d+GK_d$ 比原 $G_d$ 更小时才改善抑制；符号或模型错误也可能加重扰动。因此不能仅凭画出前馈通路就断言一定更好。形式逆还要满足稳定性、因果性、相对阶数和扰动可测等实现条件。','校正 / 前馈')
a(79,'国防科技大学','104','236–237',r'单位负反馈 $G=K_1/[s(s+K_2-1)]$。（1）写欠阻尼阶跃超调量；（2）求稳定且欠阻尼的参数范围；（3）按2%工程式 $t_s\approx4/(\zeta\omega_n)$，求 $t_s\le1$ 对 $K_2$ 的要求；（4）求单位斜坡误差。',
 r'''稳定欠阻尼要求 $K_1>0,\ 1<K_2<1+2\sqrt{K_1}$，
$$\sigma=\exp\!\left[-\frac{\pi(K_2-1)}{\sqrt{4K_1-(K_2-1)^2}}\right].$$
（3）$K_2\ge9$，同时保留上述欠阻尼限制；（4）$e_{ss}=(K_2-1)/K_1$。''',
 r'闭环分母 $s^2+(K_2-1)s+K_1$，自然频率 $\sqrt{K_1}$、阻尼比 $(K_2-1)/(2\sqrt{K_1})$。稳定需一次与常数系数均正，欠阻尼再要求判别式负。2%工程调节时间为 $8/(K_2-1)$，得第三问。单位斜坡速度系数 $K_v=K_1/(K_2-1)$。','时域分析 / 二阶性能')
a(80,'杭州电子科技大学','105','237',r'单位负反馈开环 $G=K(s+1)/(s^3+as^2+2s+1)$。闭环以频率 $2\,\mathrm{rad/s}$ 持续振荡，且另一极点在左半平面，求 $K,a$。',
 r'$K=2,a=3/4$。',r'闭环特征式为 $D=s^3+as^2+(2+K)s+1+K$。代入 $s=j2$，虚部为 $-8+2(2+K)=0$，得 $K=2$；实部 $-4a+1+K=0$，得 $a=3/4$。此时 $D=(s+3/4)(s^2+4)$，确有虚根 $\pm2j$，另一根为负实数。','时域分析 / 特征根')
a(81,'华北电力大学（北京）','105','237–240',r'闭环 $\Phi=1/(T^2s^2+2\zeta Ts+1)$，$T>0$。写出无阻尼、欠阻尼、临界阻尼、过阻尼的单位阶跃响应和极点位置，并画归一时间响应与极点示意图。',
 r'''令 $u=t/T$，各响应为
$$\begin{aligned}\zeta=0:&\quad c=1-\cos u;\\
0<\zeta<1:&\quad c=1-\frac{e^{-\zeta u}}{\sqrt{1-\zeta^2}}\sin(\sqrt{1-\zeta^2}u+\arccos\zeta);\\
\zeta=1:&\quad c=1-(1+u)e^{-u};\\
\zeta>1:&\quad c=1-e^{-\zeta u}\left[\cosh(vu)+\frac\zeta v\sinh(vu)\right],\ v=\sqrt{\zeta^2-1}.\end{aligned}$$''',
 r'极点统一为 $s=(-\zeta\pm\sqrt{\zeta^2-1})/T$。无阻尼时在虚轴 $\pm j/T$，持续振荡；欠阻尼时为左半平面复共轭根，振荡衰减；临界阻尼时为 $-1/T$ 重根，响应单调；过阻尼时为两个相异负实根，响应单调但慢实极点可拖长过程。归一时间图只比较阻尼比，不混入时间常数改变。','时域分析 / 二阶性能')
a(82,'吉林大学','105–106','240–241',r'外单位负反馈，比例 $K$ 后以正号叠加扰动，之后经 $G=K_1/[s(s+4)]$。（1）$K=4,K_1=5$，求超调、峰值及5%与2%调节时间工程值；（2）$n=0,r=(2+2t)1(t)$，求误差；（3）单位阶跃扰动下如何减小误差？',
 r'（1）超调 $e^{-\pi/2}\approx20.79\%$，峰值 $\pi/4$ 秒，5%工程时间1.5秒、2%工程时间2秒；（2）0.4；（3）扰动误差为 $-1/K$，增大 $K$ 可减小幅值。',r'闭环分母为 $s^2+4s+KK_1$，第一问常数20，得 $\omega_n=2\sqrt5,\zeta=1/\sqrt5,\omega_d=4$。误差系数 $K_v=KK_1/4=5$，斜率2的误差为2/5，阶跃分量无差。扰动通道为 $E/N=-G/(1+KG)$，零频极限为 $-1/K$。二阶模型内正增益始终稳定，但增益增大使阻尼比减小，扰动精度与动态平稳性有代价。','时域分析 / 二阶性能')
a(83,'南京邮电大学','106','241–242',r'单位负反馈系统零初值阶跃响应 $c=1-1.8e^{-4t}+0.8e^{-9t}$。（1）求开环；（2）求阻尼比、自然频率；（3）输入 $r=(2t+3)1(t)$ 的稳态误差。',
 r'$G=36/[s(s+13)]$，$\zeta=13/12,\omega_n=6$，$e_{ss}=13/18$。',r'对阶跃响应先求 $\Phi=sC=36/[(s+4)(s+9)]$。再用 $G=\Phi/(1-\Phi)$ 得开环。分母 $s^2+13s+36$ 对应自然频率6、阻尼比13/12，为过阻尼。速度系数 $36/13$，斜率2的误差为 $2/(36/13)=13/18$，阶跃分量无差。','时域分析 / 反求参数')
a(84,'南京邮电大学','106','242–244',r'单位负反馈 $G=50K/[s(s+10)]$，$K>0$。（1）求阻尼比、自然频率和超调；（2）引入反馈 $H=1+\tau s$、$\tau\ge0$，要求新闭环阻尼比0.5，求 $K,\tau$ 关系与范围。',
 r'''$\omega_n=\sqrt{50K},\ \zeta=5/\sqrt{50K}$。$0<K\le0.5$ 无超调；$K>0.5$ 时
$$\sigma=\exp\left(-\frac{5\pi}{\sqrt{50K-25}}\right).$$
（2）$K\ge2$，$\tau=(\sqrt{50K}-10)/(50K)$。''',
 r'原闭环分母为 $s^2+10s+50K$，比较标准形式即可。对过阻尼、临界阻尼应直接给零超调，不把欠阻尼公式延拓到根号非正区间。测速反馈后分母为 $s^2+(10+50K\tau)s+50K$，因此阻尼比0.5给 $10+50K\tau=\sqrt{50K}$。非负测速系数要求 $\sqrt{50K}\ge10$。','时域分析 / 二阶性能')
a(85,'南京邮电大学','107','245–247',r'单位负反馈前向为 $(1+K/s)64/[s(s+10)]$，$K\ge0$。（1）$K=0$，求 $\zeta,\omega_n$ 和超调；（2）求闭环稳定范围；（3）求全部闭环极点位于 $s=-1$ 左侧的参数范围。',
 r'（1）$\omega_n=8,\zeta=5/8$，超调 $e^{-5\pi/\sqrt{39}}\approx8.08\%$；（2）$0\le K<10$（$K=0$ 按约去退化积分支路的实际模型）；（3）$55/64<K<6$。',r'当 $K=0$，控制器实际是1，闭环为 $64/(s^2+10s+64)$。$K>0$ 时特征式为 $D=s^3+10s^2+64s+64K$，劳斯给 $0<K<10$。第三问令 $s=z-1$，得 $z^3+7z^2+47z+64K-55$，三阶条件为 $64K-55>0$、$7\times47>64K-55$，从而 $55/64<K<6$。不能把在 $K=0$ 清分母制造出的约去原点因子当成实际闭环新极点。','时域分析 / 劳斯稳定')
a(86,'南京邮电大学','107','247–250',r'负反馈前向 $G=K/[s(s+1)]$，反馈 $H=1+\tau s$。单位阶跃输入。（1）$K=2,\tau=0.2$，写响应并画图；（2）$K=10$ 时比较 $\tau=0.5$ 与0.2的响应轨迹。',
 r'''通式 $\Phi=K/[s^2+(1+K\tau)s+K]$。令 $a=(1+K\tau)/2,b=\sqrt{K-a^2}$，本题三组均有 $b>0$，
$$c(t)=1-e^{-at}\left(\cos bt+\frac a b\sin bt\right).$$
第一组 $(a,b)=(0.7,\sqrt{1.51})$；另两组分别 $(3,1)$、$(1.5,\sqrt{31}/2)$。''',
 r'直接闭合非单位反馈得到通式，三组参数分别代入。$K=10,\tau=0.5$ 时衰减率3、超调 $e^{-3\pi}\approx0.00807\%$；$\tau=0.2$ 时衰减率1.5、超调 $\exp[-3\pi/\sqrt{31}]\approx18.40\%$。两者终值均为1，但测速反馈较大的一组振荡显著减弱。图像按完整函数绘制，不使用分母参数代替实际曲线。','时域分析 / 二阶性能')
a(87,'北京科技大学','107–108','250–251',r'单位负反馈误差经 $K_1(s+0.5)/s$，以正号叠加扰动，再经 $K_2/[s(s+1)(s+2)]$ 输出，$K_1,K_2>0$。（1）求稳定条件；（2）$r=(1+t+0.3t^2)1(t)$，$n=\delta(t)+0.1\,1(t)$，求稳态误差。',
 r'$0<K_1K_2<1.5$；$e_{ss}=2.4/(K_1K_2)$。',r'令 $P=K_1K_2$，闭环分母 $D=s^4+3s^3+2s^2+Ps+0.5P$。劳斯第三行首项 $(6-P)/3$，第四行首项 $P(1.5-P)/(6-P)$，故稳定区为 $0<P<1.5$。环路为II型，$K_a=P/4$，参考二次项加速度0.6，贡献 $0.6/(P/4)=2.4/P$。控制器有积分作用，扰动位于其后，阶跃扰动误差终值为零；脉冲只激起稳定衰减响应，也不改变稳态值。','时域分析 / 劳斯稳定')
a(88,'北京科技大学','108','252',r'单位负反馈开环 $G=\omega_n^2/[s(s+2\zeta\omega_n)]$，闭环根为 $-2\pm4\sqrt2j$。（1）求 $\zeta,\omega_n$；（2）求阶跃超调、峰值和5%调节时间工程值；（3）保持自然频率不变，写无阻尼与临界阻尼的根。',
 r'$\omega_n=6,\zeta=1/3$；$\sigma=e^{-\pi/(2\sqrt2)}\approx32.93\%$，$t_p=\pi/(4\sqrt2)$ 秒，$t_s\approx1.5$ 秒；无阻尼根 $\pm6j$，临界阻尼重根 $-6$。',r'极点模长为 $\sqrt{(-2)^2+(4\sqrt2)^2}=6$，负实部为 $\zeta\omega_n=2$。阻尼振荡频率 $4\sqrt2$，故超调指数为 $-2\pi/(4\sqrt2)$。5%工程调节时间 $3/2$。固定自然频率6后，分别令阻尼比0和1，代入标准根公式。','时域分析 / 二阶性能')

a(89,'东南大学','109','253',r'单位负反馈开环 $G=K(s+2)/[s(s+1)(2s+1)]$。输入单位斜坡，先求稳定条件与稳态误差，再求误差严格小于0.25的稳定 $K$ 范围。',
 r'$0<K<3$ 时稳定，$e_{ss}=1/(2K)$；满足严格误差要求的范围为 $2<K<3$。',r'闭环特征式 $2s^3+3s^2+(1+K)s+2K$。三阶稳定条件为 $K>0$、$3(1+K)>4K$，得 $K<3$。速度系数为 $\lim sG=2K$，所以误差 $1/(2K)$。严格小于0.25给 $K>2$；等于2只达到边界，不应包含。','时域分析 / 劳斯稳定')
a(90,'东北林业大学','109','253–255',r'单位负反馈 $G=K(0.5s+1)/[s(s+1)(0.5s^2+s+1)]$。求闭环稳定范围。',
 r'$0<K<3\sqrt5-5$。',r'闭环清分母得 $D=s^4+3s^3+4s^2+(2+K)s+2K$。劳斯首列为 $1,3,(10-K)/3,(-K^2-10K+20)/(10-K),2K$。同正要求 $K>0,K<10,K^2+10K-20<0$，交集为所列区间。上端约1.7082，端点处不再渐近稳定。','时域分析 / 劳斯稳定')
a(91,'南开大学（专硕）','109–110','255–256',r'系统 $E=R-C$、$V=(K/s)(E-\beta V)$、$C=(V-G_nN)/s+N$，$K>0$。（1）求 $C/R$；（2）求外环开环幅频特性单调递减的 $\beta$ 条件；（3）设计 $G_n$ 使扰动全过程无影响。',
 r'$C/R=K/(s^2+K\beta s+K)$。开环幅频曲线对任意实 $\beta$ 均递减；若同时要求闭环稳定需 $\beta>0$。完全补偿 $G_n=s$。',r'闭合局部反馈后，外环开环为 $L=K/[s(s+K\beta)]$，幅值为 $K/[\omega\sqrt{\omega^2+K^2\beta^2}]$，对任意实 $\beta$ 及 $\omega>0$ 均严格递减。但稳定性还需检查分母系数，得 $\beta>0$。扰动通道分子为 $(s+K\beta)(s-G_n)$，因此取 $G_n=s$ 可恒等抵消。不要把“闭环无谐振峰”条件误用到本题的开环幅频单调性。','校正 / 前馈')
a(92,'厦门大学','110','256–257',r'典型无零点二阶单位负反馈系统，单位阶跃终值1，首峰约1.36、峰值时间0.5秒，题给 $\zeta=0.309$。列自然频率、开环函数与5%调节时间工程值的计算公式，不必计算数值。',
 r'$$\omega_n=\frac{2\pi}{\sqrt{1-0.309^2}},\quad G=\frac{\omega_n^2}{s(s+2\zeta\omega_n)},\quad t_s\approx\frac3{0.309\omega_n}.$$ ',r'峰值时间 $t_p=\pi/[\omega_n\sqrt{1-\zeta^2}]$，代入0.5秒即可解自然频率。闭环为 $\omega_n^2/(s^2+2\zeta\omega_ns+\omega_n^2)$，逆用单位负反馈关系得开环。图示36%超调与阻尼比0.309在读图精度下相符，采用题给阻尼比计算。','时域分析 / 反求参数')
a(93,'厦门大学','111','257–258',r'求解 $\ddot y+2\dot y-3y=e^{-t}$，$t\ge0$，满足 $y(0)=1,\dot y(0)=0$。',
 r'$y(t)=\tfrac78e^t-\tfrac14e^{-t}+\tfrac38e^{-3t}$。',r'齐次特征根为1与-3，特解取 $Ae^{-t}$，代入得 $-4A=1$，故 $A=-1/4$。写总解 $C_1e^t+C_2e^{-3t}-(1/4)e^{-t}$，初值给 $C_1+C_2=5/4$、$C_1-3C_2=-1/4$，解得 $C_1=7/8,C_2=3/8$。也可用单边拉氏变换得到同样分式。','数学基础 / 微分方程')
a(94,'重庆邮电大学','111','258–259',r'系统 $C=K[R-C-0.25sC]/[s(s+4)(s+8)]$。要求有一对根的阻尼比 $1/\sqrt2$，求 $K$、全部闭环极点及单位斜坡稳态误差。',
 r'$K=128$，闭环根 $-4,-4\pm4j$，$e_{ss}=0.5$。',r'特征式为 $D=s^3+12s^2+(32+K/4)s+K$。设复根为 $-a\pm ja$、第三根为 $-b$，则 $D=(s+b)(s^2+2as+2a^2)$。比较系数得到 $b+2a=12$、$2a^2+2ab=32+K/4$、$2a^2b=K$，消元为 $(a-4)(a^2-4a+8)=0$。实解 $a=b=4$，得增益128。外误差 $E=R-C$ 的单位斜坡终值为 $(32+K/4)/K=1/2$。','时域分析 / 反求参数')
a(95,'北京交通大学','111–112','260–262',r'单位负反馈控制器 $G_c$ 后以正号叠加扰动，再经 $1/[s(s+2)]$ 输出。（1）比例控制时使单位斜坡误差0.5，求增益；（2）设计最简单稳定控制器使单位斜坡无差；（3）$G_c=10/(s+3)$、$R=1/s^2,N=0.5/s$，求总误差。',
 r'（1）$K_c=4$；（2）可取 PI 控制器 $G_c=k_p+k_i/s$，$k_p>0,0<k_i<2k_p$；（3）$e_{ss}=0.45$。',r'''比例控制闭环分母 $s^2+2s+K_c$，单位斜坡误差 $2/K_c=0.5$ 得4。仅加积分控制 $k_i/s$ 会使特征式 $s^3+2s^2+k_i$ 缺一次项而不稳定；加比例项后为 $s^3+2s^2+k_ps+k_i$，劳斯条件即第二问范围。
第三问特征式为 $s(s+2)(s+3)+10=s^3+5s^2+6s+10$，满足稳定条件。参考斜坡速度系数 $G_c(0)/2=5/3$，贡献0.6；扰动误差低频为 $-1/G_c(0)=-0.3$，幅值0.5贡献-0.15，总和0.45。''','校正 / PID 控制')
a(96,'北京交通大学','112–113','262–264',r'外误差 $E=R-C$。控制前向依次为 $K,1/(0.5s+1),1/(0.1s+1)$，扰动在最后环节前以正号叠加。开关P闭合时，在最初比较点另减去 $K_tsC$。（1）P断开、$N=0,K=4$，求阶跃响应和误差；（2）P闭合、$N=0$，按 $\zeta=0.7$ 对应超调约4.6%，且5%工程时间 $3/(\zeta\omega_n)=0.1$ 秒，求参数；（3）P断开、$R=0,N=1/s$，求 $|e_{ss}|\le0.01$ 的 $K>0$ 范围。',
 r'（1）$c=0.8[1-e^{-6t}(\cos8t+0.75\sin8t)]$，误差0.2；（2）$K=4451/49\approx90.8367,K_t=588/22255\approx0.026421$；（3）$K\ge99$。',r'第一问闭环为 $80/(s^2+12s+100)$，终值0.8。闭合速度反馈后分母为 $s^2+(12+20KK_t)s+20(1+K)$。由 $\zeta\omega_n=30$ 和 $\zeta=0.7$ 得 $\omega_n=300/7$，比较常数项、一次项得到参数。注意原题误差为 $R-C$，即使引入速度反馈也仍按外误差定义。第三问扰动稳态输出 $1/(1+K)$，误差负号不影响绝对值约束，故 $1/(1+K)\le0.01$ 给 $K\ge99$。','时域分析 / 二阶性能')
a(97,'北京邮电大学','113','264–266',r'无零点单位负反馈系统，闭环特征式 $s^3+7s^2+12s+10$，单位阶跃误差零。（1）求开环和斜坡误差；（2）求完整模型阶跃超调与精确2%调节时间，同时给主导二阶近似。',
 r'$G=10/[s(s+3)(s+4)]$，斜坡误差1.2。完整模型超调4.1018%，2%调节4.4203秒；主导近似 $2/(s^2+2s+2)$。',r'无零点闭环分子为常数，阶跃无差要求 $\Phi(0)=1$，故分子等于10。由 $G=\Phi/(1-\Phi)$ 得开环，$K_v=10/12$，斜坡误差1.2。闭环分母因式分解 $(s+5)(s^2+2s+2)$，稳定。精确阶跃响应为 $c=1-(2/17)e^{-5t}-(15/17)e^{-t}\cos t-(25/17)e^{-t}\sin t$。求导数零点和最后2%交点得到所列指标。忽略快极点-5可得二阶近似，近似超调 $e^{-\pi}$，应与完整值区分。','时域分析 / 主导极点')
a(98,'北京邮电大学','113','266–267',r'前向 $10/[s^2(s+10)]$，反馈 $1+K_ts$。（1）求稳定的 $K_t$；（2）一根为 $-5$，求 $K_t$ 与零初值单位阶跃响应。',
 r'''$K_t>0.1$；第二问 $K_t=2.7$，
$$c(t)=1-e^{-5t}-\frac{10}{\sqrt{17}}e^{-5t/2}\sinh\frac{\sqrt{17}t}{2}.$$ ''',
 r'特征式 $D=s^3+10s^2+10K_ts+10$。劳斯首列 $1,10,10K_t-1,10$ 给第一问。代 $s=-5$ 得 $135-50K_t=0$，因此2.7且 $D=(s+5)(s^2+5s+2)$。阶跃输出分解为 $C=1/s-1/(s+5)-5/(s^2+5s+2)$。用平方配方或两个实极点反变换得到双曲正弦式；初始值0、终值1。','时域分析 / 劳斯稳定')
a(99,'大连海事大学','114','267–269',r'系统 $E=R-C$、$V=(E-K_2sC)/s+K_3R$、$C=(K_1/s)V$。$K_3=0$ 时，阶跃超调16.3%（按阻尼比0.5），单位斜坡误差0.25。（1）求 $K_1,K_2$；（2）用梅森公式写闭环函数，设计 $K_3$ 使单位斜坡无差。',
 r'$K_1=16,K_2=0.25$，$\Phi=K_1(1+K_3s)/(s^2+K_1K_2s+K_1)$，$K_3=0.25$。',r'两负反馈回路增益为 $-K_1/s^2$ 与 $-K_1K_2/s$，无互不接触回路，梅森特征式为 $1+K_1K_2/s+K_1/s^2$。两前向通路增益为 $K_1/s^2$ 与 $K_1K_3/s$，余因子均1，合并得闭环。无前馈时斜坡误差等于 $K_2$，结合阻尼比求出 $K_1$。有前馈时误差低频系数为 $K_2-K_3$，所以取两者相等。','时域分析 / 反求参数')
a(100,'大连理工大学','114–115','269–273',r'单位负反馈，前级 $G_1$ 的单位阶跃响应为 $2(1-e^{-3t})$；其后以正号叠加经 $1/(2s+1)$ 的扰动，再经 $2/(s+4)$ 输出。（1）$r=10\,1(t),n=0$，求终值；（2）求超调、峰值、精确5%调节时间及误差；（3）设计从 $n$ 到 $G_1$ 输入端的前馈，使阶跃扰动稳态影响消除，另给完全补偿式。',
 r'（1）5；（2）超调4.0448%，峰值0.9165秒，精确5%调节0.6045秒，误差5；（3）常值前馈取 $-1/2$ 足以消除阶跃稳态影响，完全补偿为 $-(s+3)/[6(2s+1)]$。',r'$G_1=6/(s+3)$，故 $\Phi=12/(s^2+7s+24)$。自然频率 $2\sqrt6$、衰减率3.5、阻尼振荡频率 $\sqrt{47}/2$，终值为参考幅度的一半。超调为 $\exp(-7\pi/\sqrt{47})$，峰值 $2\pi/\sqrt{47}$。因正超调小于5%，精确5%调节为响应首次达到终值95%的时刻；按工程 $3/3.5$ 则估算0.8571秒，不能将其称为精确值。扰动补偿要求 $G_1G_f+1/(2s+1)$ 在零频为零，故 $G_f(0)=-1/2$；全过程要求该式恒零。','校正 / 前馈')
a(101,'电子科技大学（839）','115','273',r'闭环特征多项式 $D=s^4+2s^3+s^2+2s+K$。讨论实参数 $K$ 对稳定性的影响。',
 '任何实数K都不能使系统渐近稳定。K>0有2个右半平面根；K<0有1个；K=0含原点及一对虚轴根。',r'劳斯表 $s^2$ 行首项为0但该行并非全零，取正 $\varepsilon$。首列为 $1,2,\varepsilon,2-2K/\varepsilon,K$。$K>0$ 时符号 $+,+,+,-,+$，两次变号；$K<0$ 时 $+,+,+,+,-$，一次变号。$K=0$ 时直接分解 $D=s(s+2)(s^2+1)$，根为0、-2、$\pm j$，不存在渐近衰减；仅在自由运动有界的意义下可称临界。','时域分析 / 劳斯稳定')
a(102,'电子科技大学（839）','115–116','273–274',r'无零点系统前向 $K/[s(s+a)]$，常数负反馈 $h$。单位阶跃终值3、首峰4.32；首峰到紧邻谷值的时间为6.49秒。（1）求 $a,K,h$；（2）求精确2%调节时间，并给 $4/(\zeta\omega_n)$ 工程值。',
 r'令 $\alpha=-\ln0.44/6.49,b=\pi/6.49$。$h=1/3,a=2\alpha\approx0.252999,K=3(\alpha^2+b^2)\approx0.750968$；精确2%调节约28.1784秒，工程估算约31.62秒。',r'终值为 $1/h$，所以 $h=1/3$。相对超调 $(4.32-3)/3=0.44$；首峰到下一谷值是半个阻尼周期，故阻尼振荡频率 $b=\pi/6.49$。超调 $e^{-\alpha\pi/b}=0.44$，给衰减率 $\alpha$，自然频率平方为 $\alpha^2+b^2=Kh$，由此求全部参数。精确归一响应为 $1-e^{-\alpha t}[\cos bt+(\alpha/b)\sin bt]$，求最后2%误差带交点。题给对数提示只有ln0.4，若粗略代替ln0.44会改变阻尼比，不能作为精确数据。','时域分析 / 反求参数')
a(103,'电子科技大学（862）','116','274–275',r'外单位负反馈控制器为 $K_1+T_1s$，扰动在控制器之后以负号叠加，对象 $K_2/[s(T_2s+1)]$，$K_2,T_2>0,T_1\ge0$。参考为0、扰动为单位阶跃，要求 $e=-c$ 的终值0.01，求 $K_1$ 并判稳。',
 r'$K_1=100$，闭环稳定。',r'闭环特征式 $T_2s^2+(1+K_2T_1)s+K_1K_2$。正参数下各系数为正，二阶稳定。由于扰动以负号输入对象，误差通道为 $E/N=K_2/D$，单位阶跃终值为 $K_2/(K_1K_2)=1/K_1$。解等于0.01得100，不能遗漏扰动符号而得到负增益。','时域分析 / 稳态误差')
a(104,'电子科技大学（862）','116','275–278',r'单位负反馈开环 $G=K/[s(s+1)]$。（1）写欠阻尼区的首次达到终值上升时间、峰值时间、超调及5%与2%调节时间工程公式；（2）分析 $K$ 对各类阶跃响应的影响。',
 r'''稳定要求 $K>0$，欠阻尼区 $K>1/4$，令 $d=\sqrt{4K-1}$，
$$t_r=\frac{2[\pi-\arccos(1/(2\sqrt K))]}d,\quad t_p=\frac{2\pi}d,\quad\sigma=e^{-\pi/d}.$$
5%按3系数估算为6秒，2%按4系数估算为8秒；这些是工程估算。''',
 r'闭环 $K/(s^2+s+K)$，自然频率 $\sqrt K$、阻尼比 $1/(2\sqrt K)$，乘积恒为0.5。$0<K<1/4$ 为过阻尼，两负实根中慢根随K增加向左移，响应通常加快；$K=1/4$ 为-0.5重根；$K>1/4$ 为共轭根，实部始终-0.5，振荡频率随K增大，超调增大、峰值时间缩短。工程调节时间固定并不意味着精确误差带的最后交点严格不变。','时域分析 / 二阶性能')
a(105,'电子科技大学（862）','117','278–279',r'系统 $E=X_i-X_o$，误差进入第二比较点后减去 $K_2V$，经 $K_1/(Ts+a)$ 得到 $V$，再经 $1/s$ 输出。$T,a,K_1,K_2>0$。（1）求单位阶跃误差；（2）求单位斜坡误差；（3）讨论两增益的影响。',
 r'阶跃误差0；斜坡误差 $a/K_1+K_2$。增大 $K_1$ 降低斜坡误差，但有限 $K_2>0$ 构成其下界；增大 $K_2$ 使误差增大。',r'先闭合速度局部环，外环开环 $L=K_1/[s(Ts+a+K_1K_2)]$。闭环分母 $Ts^2+(a+K_1K_2)s+K_1$，正参数下稳定。该外环为I型，阶跃零误差；$K_v=K_1/(a+K_1K_2)$，斜坡误差为倒数。$T$ 不影响这一低频误差系数，但影响动态性能。','时域分析 / 稳态误差')
rr,count=routh([1,9,20,2,2]);assert count==0
a(106,'电子科技大学（862）','117','279–280',r'单位负反馈 $G=2(s+1)/[s^2(s+4)(s+5)]$，输入 $r=(2+4t^2)1(t)$。先判稳，再求稳态误差。',
 r'闭环稳定，$e_{ss}=80$。',r'闭环特征多项式 $s^4+9s^3+20s^2+2s+2$。'+'\n\n'+rr+r'\n\n系统II型，阶跃误差为零，$K_a=\lim s^2G=2/(4\cdot5)=0.1$。二次输入4t²的加速度为8，故误差为 $8/0.1=80$。本题与另一道闭环不稳定的II型题必须分别判稳，不能因为型别相同就照搬结果。','时域分析 / 稳态误差')
a(107,'河北工业大学','117','280–281',r'稳定闭环 $\Phi(s)=B(s)/A(s)$，$A=a_ns^n+\cdots+a_1s+a_0$、$B=b_ms^m+\cdots+b_1s+b_0$，$n>m,a_0\ne0$，缺少的分子系数视为0。误差 $e=r-c$。分别求阶跃、斜坡及单位加速度输入零稳态误差的充要低频系数条件。',
 r'阶跃：$a_0=b_0$；斜坡：再要求 $a_1=b_1$；加速度：再要求 $a_2=b_2$。',r'误差通道 $1-\Phi=(A-B)/A$。输入分别为 $1/s,1/s^2,1/s^3$，要使误差终值为0，分子 $A-B$ 在原点至少分别具有1、2、3阶零点。由于 $A(0)\ne0$，分母不改变零点阶数，所列系数逐项相等正是相应条件。闭环稳定保证剩余指数模态衰减，若没有稳定性前提，仅比较低频系数不足以推出实际稳态误差。','时域分析 / 稳态误差')
a(108,'郑州大学','118','281–283',r'零初值电路：输入依次经过 $R_1\parallel C_1$、电感 $L$，最后经 $R_2,C_2$ 串联接地。输出为 $R_2,C_2$ 整段电压。结构图变量满足 $I=G_1(U_i-U_{c1}-U_{c2})$、$U_{c2}=G_2I$、$U_o=U_{c2}+G_3I$、$U_{c1}=G_4I$。（1）求四个环节；（2）求 $U_o/U_i$；（3）说明正元件参数的稳定性。',
 r'''$$G_1=\frac1{Ls+R_2},\quad G_2=\frac1{C_2s},\quad G_3=R_2,\quad G_4=\frac{R_1}{1+R_1C_1s}.$$
$$\frac{U_o}{U_i}=\frac{(1+R_1C_1s)(1+R_2C_2s)}{a_3s^3+a_2s^2+a_1s+1},$$
其中 $a_3=R_1C_1C_2L$，$a_2=R_1R_2C_1C_2+C_2L$，$a_1=R_1C_1+R_1C_2+R_2C_2$。所有元件严格为正时渐近稳定。''',
 r'电感与 $R_2$ 的电压和为 $U_i-U_{c1}-U_{c2}$，从而确定 $G_1$；其余环节直接由电阻、电容与并联RC阻抗关系确定。输入总阻抗为 $R_1/(1+R_1C_1s)+Ls+R_2+1/(C_2s)$，输出阻抗为 $R_2+1/(C_2s)$，分压并清分母得通式。三阶劳斯条件为 $a_i>0$ 且 $a_2a_1>a_3$。对于严格正元件，后一差值展开后各剩余项均为正，故自动满足；不必把它误当成还需另加的独立物理限制。','建模 / 传递函数')
a(109,'哈尔滨工业大学','119','283–284',r'转动惯量 $J>0$ 的负载经黏性阻尼 $f>0$ 接固定基座，主动转矩 $T$，角位移 $\theta$。（1）列运动方程及 $\Theta/T$；（2）以该对象串接输出比例负反馈 $K$，求闭环稳定且阶跃响应无超调的 $K$ 范围。',
 r'$J\ddot\theta+f\dot\theta=T$，$G=1/[s(Js+f)]$；无超调稳定范围 $0<K\le f^2/(4J)$。',r'阻尼力矩与角速度反向，故运动方程中为正阻尼项。反馈闭合后传递函数为 $1/(Js^2+fs+K)$。稳定需 $K>0$；该无零点二阶系统无超调等价于两个负实根（含重根），故判别式 $f^2-4JK\ge0$。与稳定条件相交得到答案。','建模 / 机械系统')
a(110,'天津大学','119–120','284–285',r'质量 $m>0$ 的平移物体经并联弹簧 $k>0$、阻尼器 $b>0$ 与墙相连，忽略其他摩擦，力输入 $F(t)$，位移 $y$，零初值。（1）求 $Y/F$；（2）$0<b<2\sqrt{mk}$，求 $\zeta,\omega_n$；（3）输入3牛顿阶跃力，求最终位移。',
 r'$Y/F=1/(ms^2+bs+k)$；$\omega_n=\sqrt{k/m},\zeta=b/(2\sqrt{mk})$；终值 $3/k$。',r'牛顿定律给 $m\ddot y=F-b\dot y-ky$，整理并变换得到函数。除以m后与标准二阶式比较，获得阻尼比与自然频率。题给阻尼范围使 $0<\zeta<1$，系统稳定且欠阻尼；最终弹簧力平衡外力，$ky=3$，亦可由终值定理求得。','建模 / 机械系统')
a(111,'武汉科技大学','120–121','285–286',r'柔性轴模型 $J_l\ddot\theta_l+K(\theta_l-\theta_m)=0$、$J_m\ddot\theta_m-K(\theta_l-\theta_m)=u$。此处 $\theta_l,\theta_m$ 明确定义为角位移，角速度为其导数。（1）分别求电机角位移和角速度相对力矩的传递函数及极点；（2）图示按电机角位移作单位负反馈，$J_l=J_m=K=1$，PD控制器 $K_p+K_Ds$，求稳定范围。',
 r'''$$\frac{\Theta_m}{U}=\frac{J_ls^2+K}{s^2[J_lJ_ms^2+(J_l+J_m)K]}.$$
角位移有两个原点极点及一对纯虚根；角速度通道乘以s，只有一个原点极点及同一对纯虚根。第二问 $K_p>0,K_D>0$。''',
 r'由负载方程消去 $\Theta_l$ 得传递函数。位移分母含刚体双积分模态和无阻尼弹性模态，不能因题本文字写“转速”就将角位移与角速度混为一谈。第二问对象 $(s^2+1)/[s^2(s^2+2)]$，闭环特征式为 $s^4+K_Ds^3+(2+K_p)s^2+K_Ds+K_p$。劳斯首列为 $1,K_D,1+K_p,K_D/(1+K_p),K_p$，同正恰得 $K_p,K_D>0$。','建模 / 机械系统','纠正题本把二阶运动方程中的角位移称作转速的变量不一致；题干直接区分角位移与角速度，并明确图中的反馈量。')
a(112,'上海大学','121','286–287',r'电路为 $R_1\parallel C_1$ 与 $R_2$、$C_2$ 串联，输出为 $C_2$ 两端电压 $u_c$。$R_1=0.5\Omega,R_2=1\Omega,C_1=2\mathrm F,C_2=1\mathrm F$。$t\ge0$ 输入保持1伏，$u_c(0^+)=0.1$伏，流入串联网络的总电流 $i_r(0^+)=0.1$安。先列微分方程、再变换求 $u_c(t)$。',
 r'$\ddot u_c+2.5\dot u_c+u_c=\dot u+u$，$u_c(t)=1-(17/15)e^{-t/2}+(7/30)e^{-2t}$。',r'总阻抗法给 $U_c/U=(1+R_1C_1s)/[R_1R_2C_1C_2s^2+(R_1C_1+R_1C_2+R_2C_2)s+1]$，代数值得微分方程。对 $t>0$ 输入导数为零；输出电容电流等于总电流，所以 $\dot u_c(0^+)=i_r(0^+)/C_2=0.1$。单边变换得 $(s^2+2.5s+1)U_c=1/s+0.1s+0.35$。分解成 $1/s-(17/15)/(s+0.5)+(7/30)/(s+2)$ 后反变换，初值和导数均可回代核查。','建模 / 传递函数')
a(113,'华东理工大学','122','288–289',r'质量块经弹簧 $k$ 和阻尼 $b$ 与地连接，力输入 $x$，位移 $y$，零初值。施加1牛顿阶跃后终值0.5米，阻尼比0.2。按题图的2%工程调节时间读数 $t_s=4$ 秒，并统一采用 $t_s\approx4/(\zeta\omega_n)$，求 $Y/X$ 与元件参数。',
 r'$k=2\,\mathrm{N/m},m=0.08\,\mathrm{kg},b=0.16\,\mathrm{N\,s/m}$，$Y/X=12.5/(s^2+2s+25)$。',r'运动方程 $m\ddot y+b\dot y+ky=x$。1牛顿下终值0.5米给 $k=1/0.5=2$。按题干明确的工程公式，$4=4/(0.2\omega_n)$ 得 $\omega_n=5$。因此 $m=k/\omega_n^2=0.08$，$b=2\zeta\omega_nm=0.16$。将三个参数代入即可得到传递函数。图中0.49相对于0.5偏差2%，按答案册将其用于工程调节时间读数；这些估计不应再称作完整响应的精确拟合。','建模 / 机械系统','图示与典型二阶曲线并非精确一致；按答案册以0.49确定2%误差带及4秒工程读数的解释，把近似约定直接写入题干。')

